/// The normalization epsilon a model starts with: the Cargo default, which is also
/// the value every bundle saved before models carried their own was lowered with.
fn default_epsilon() -> Result<f64> {
	number("normalization epsilon", env!("RECIPE_NORMALIZATION_EPSILON"))
}
fn number(name: &str, text: &str) -> Result<f64> {
	let value = text.parse::<f64>().map_err(|error| RecipeError::new(format!("invalid {name}: {error}")))?;
	(value.is_finite() && value > 0.0).then_some(value).ok_or_else(|| RecipeError::new(format!("{name} must be finite and positive")))
}
fn fraction(name: &str, text: &str) -> Result<f64> {
	let value = number(name, text)?;
	require(value <= 1.0, format!("{name} must not exceed one")).map(|_| value)
}
fn natural(name: &str, text: &str) -> Result<usize> {
	let value = count(name, text)?;
	require(value != 0, format!("{name} must be positive")).map(|_| value)
}
fn count(name: &str, text: &str) -> Result<usize> {
	text.parse::<usize>().map_err(|error| RecipeError::new(format!("invalid {name}: {error}")))
}
fn stored_graph(graph: &Graph, model: &Model, data: &Data, scale: Option<TargetScale>, precision: Compute, target: &str) -> bundle::StoredGraph {
	let inputs = (0..graph.input.elements()).map(|index| format!("input{index}")).collect();
	let (norm_mean, norm_scale) = match data.prepared.get() {
		Some(Ok(prepared)) => (prepared.norm_mean.clone(), prepared.norm_scale.clone()),
		_ => (Vec::new(), Vec::new()),
	};
	let (target_min, target_span) = scale.map_or((0.0, 0.0), |s| (s.minimum, s.span));
	let schema = data.prepared.get().and_then(|prepared| prepared.as_ref().ok()).map_or_else(DataSchema::default, |prepared| prepared.schema.clone());
	// Every selected target column is an output, in the order the user declared them.
	let outputs = if data.autoregressive {
		vec!["char-id".to_owned()]
	} else if data.target.is_empty() {
		vec!["target".to_owned()]
	} else {
		schema.iter().filter(|(kind, _)| kind == "target").map(|(_, name)| name.clone()).collect()
	};
	let artifact = bundle::artifact_key(model, &schema, precision, graph, target);
	bundle::StoredGraph { graph: graph.clone(), model: model.clone(), precision, inputs, outputs, norm_mean, norm_scale, target_min, target_span, bn_stats: Vec::new(), artifact }
}
/// A host-gathered table of one lookup node: the rows every token addresses are
/// decoded on the host and staged in the node's context as [row][position][channel]
/// for the positions a forward writes.
struct HostLookup {
	context: usize,
	/// The arithmetic of the node that reads this table.
	precision: Compute,
	hash: Option<RowHash>,
	table: StoredWeight,
	width: usize,
	length: usize,
}
enum LogitsMessage {
	Bytes(Vec<u8>),
	Flush(std::sync::mpsc::Sender<std::result::Result<(), String>>),
}
/// The `RECIPE_ALL_LOGITS` file and the one thread that appends `record_logits` bytes
/// to it in order, so a decode step does not wait for the file.
fn logits_writer() -> Option<&'static std::sync::mpsc::Sender<LogitsMessage>> {
	static WRITER: OnceLock<Option<std::sync::mpsc::Sender<LogitsMessage>>> = OnceLock::new();
	WRITER.get_or_init(|| {
		let path = std::env::var("RECIPE_ALL_LOGITS").ok().filter(|path| !path.is_empty())?;
		let (sender, receiver) = std::sync::mpsc::channel::<LogitsMessage>();
		std::thread::spawn(move || {
			let mut failure = None;
			for message in receiver {
				match message {
					LogitsMessage::Bytes(bytes) if failure.is_none() => {
						let written = fs::OpenOptions::new().create(true).append(true).open(&path).map_err(|error| format!("cannot open {path}: {error}"))
							.and_then(|mut file| std::io::Write::write_all(&mut file, &bytes).map_err(|error| format!("cannot write {path}: {error}")));
						failure = written.err();
					}
					LogitsMessage::Bytes(_) => {}
					LogitsMessage::Flush(reply) => { let _ = reply.send(failure.take().map_or(Ok(()), Err)); }
				}
			}
		});
		Some(sender)
	}).as_ref()
}
/// Wait until every recorded logit is in the file.
fn flush_logits() -> Result<()> {
	let Some(writer) = logits_writer() else { return Ok(()) };
	let (reply, done) = std::sync::mpsc::channel();
	writer.send(LogitsMessage::Flush(reply)).map_err(|_| RecipeError::new("the logits writer has stopped"))?;
	done.recv().map_err(|_| RecipeError::new("the logits writer has stopped"))?.map_err(RecipeError::new)
}
#[derive(Default)]
struct LookupRows {
	rows: std::collections::HashMap<(usize, usize), (Vec<f64>, u64)>,
	order: std::collections::BTreeMap<u64, (usize, usize)>,
	bytes: usize,
	clock: u64,
	hits: u64,
	misses: u64,
}
impl LookupRows {
	const LIMIT: usize = 64 << 20;
	fn append(&mut self, lookup: usize, table: &HostLookup, row: usize, output: &mut Vec<f64>) -> Result<()> {
		let key = (lookup, row);
		self.clock = self.clock.checked_add(1).ok_or_else(|| RecipeError::new("lookup row cache age overflows"))?;
		if let Some((values, age)) = self.rows.get_mut(&key) {
			self.order.remove(age);
			*age = self.clock;
			self.order.insert(*age, key);
			self.hits += 1;
			output.extend_from_slice(values);
			return Ok(());
		}
		self.misses += 1;
		// Decoding touches only this requested row in the original mapped table.
		let values = ngram::table_row(&table.table, table.width, row)?;
		let bytes = values.capacity() * size_of::<f64>();
		output.extend_from_slice(&values);
		if bytes > Self::LIMIT { return Ok(()); }
		while self.bytes + bytes > Self::LIMIT {
			let (_, oldest) = self.order.pop_first().ok_or_else(|| RecipeError::new("lookup row cache eviction order is empty"))?;
			let (values, _) = self.rows.remove(&oldest).ok_or_else(|| RecipeError::new("lookup row cache eviction row is absent"))?;
			self.bytes -= values.capacity() * size_of::<f64>();
		}
		self.bytes += bytes;
		self.order.insert(self.clock, key);
		self.rows.insert(key, (values, self.clock));
		Ok(())
	}
}
