struct NativeRequest {
	input: Buffer,
	output: Buffer,
	hidden: Buffer,
	lookups: Vec<Buffer>,
	begin: u32,
	positions: usize,
}
impl NativeRequest {
	fn new(gpu: &'static Gpu) -> Result<Self> {
		Ok(Self { input: Buffer::zeroed(gpu, 1)?, output: Buffer::zeroed(gpu, 1)?, hidden: Buffer::zeroed(gpu, 1)?, lookups: Vec::new(), begin: 0, positions: 0 })
	}
	fn grow(buffer: &mut Buffer, bytes: usize) -> Result<()> {
		if bytes > buffer.bytes { *buffer = Buffer::zeroed(buffer.runtime, bytes)?; }
		Ok(())
	}
	fn shadow(&self) -> Result<Self> {
		let copy = |buffer: &Buffer| Buffer::upload(buffer.runtime, &buffer.download::<u8>(buffer.bytes)?);
		Ok(Self {
			input: copy(&self.input)?, output: copy(&self.output)?, hidden: copy(&self.hidden)?,
			lookups: self.lookups.iter().map(copy).collect::<Result<Vec<_>>>()?, begin: self.begin, positions: self.positions,
		})
	}
}

#[derive(Clone, Copy)]
#[repr(i32)]
enum ForwardMode {
	Inference,
	Training,
	StateOnly,
}

#[derive(Clone, Copy, Debug)]
enum EpochOperation {
	Full,
	Gradient,
	Optimizer,
	Metrics,
}

#[derive(Clone, Copy, Default)]
struct EpochMetrics {
	loss: f64,
	target_mean: f64,
	target_m2: f64,
	residual_square: f64,
	prediction_sum: f64,
	r2: f64,
	count: usize,
	device_seconds: f64,
}
impl EpochMetrics {
	const VALUES: usize = 6;
	fn read(values: &[f64], count: usize, device_seconds: f64) -> Self {
		Self { loss: values[0], target_mean: values[1], target_m2: values[2], residual_square: values[3], r2: values[4], prediction_sum: values[5], count, device_seconds }
	}
	fn predicted_mean(self) -> f64 { self.prediction_sum / self.count as f64 }
	fn combine(parts: impl IntoIterator<Item = (Self, f64)>, root_loss: bool) -> Self {
		let parts = parts.into_iter().collect::<Vec<_>>();
		let (mut target_mean, mut target_m2, mut count) = (0.0, 0.0, 0_usize);
		for (part, _) in &parts {
			if part.count == 0 { continue; }
			let next = count + part.count;
			let delta = part.target_mean - target_mean;
			target_m2 += part.target_m2 + delta * delta * count as f64 * part.count as f64 / next as f64;
			target_mean += delta * part.count as f64 / next as f64;
			count = next;
		}
		let residual_square = parts.iter().map(|(part, _)| part.residual_square).sum();
		let prediction_sum = parts.iter().map(|(part, _)| part.prediction_sum).sum();
		let loss = if root_loss { parts.iter().map(|(part, share)| share * part.loss * part.loss).sum::<f64>().sqrt() } else { parts.iter().map(|(part, share)| share * part.loss).sum() };
		let r2 = if target_m2 == 0.0 { 0.0 } else { 1.0 - residual_square / target_m2 };
		let device_seconds = parts.iter().map(|(part, _)| part.device_seconds).fold(0.0, f64::max);
		Self { loss, target_mean, target_m2, residual_square, prediction_sum, r2, count, device_seconds }
	}
}

impl EpochOperation {
	fn gradient(self) -> bool {
		matches!(self, Self::Full | Self::Gradient)
	}
	fn optimizer(self) -> bool {
		matches!(self, Self::Full | Self::Optimizer)
	}
}
/// Inputs accepted by an inference tape. Ordinary feature values stay `f64`;
/// embedding models carry token IDs as integers so the host never recodes them
/// through a floating-point intermediate.
#[derive(Clone, Copy)]
enum TapeInput<'a> {
	Values(&'a [f64]),
	Ids(&'a [u32]),
	Zeroed(usize),
}
impl TapeInput<'_> {
	fn len(self) -> usize {
		match self {
			Self::Values(values) => values.len(),
			Self::Ids(ids) => ids.len(),
			Self::Zeroed(count) => count,
		}
	}
	fn label(self) -> &'static str {
		match self {
			Self::Values(_) => "values",
			Self::Ids(_) => "token ids",
			Self::Zeroed(_) => "zero-initialized values",
		}
	}
}
/// The context regions a tape fills before its first forward: one nearest
/// index per predictor node that runs a nearest program.
fn native_context_regions(graph: &Graph, layout: &NativeLayout, weights: &Buffer, precision: Compute) -> Result<Vec<(usize, Vec<u8>)>> {
	let _ = precision;
	let mut regions = Vec::new();
	let nearest = graph.nodes.iter().map(|node| nearest_layout(node, &graph.programs)).collect::<Result<Vec<_>>>()?;
	if nearest.iter().all(Option::is_none) {
		return Ok(regions);
	}
	for (index, (node, nearest)) in graph.nodes.iter().zip(nearest).enumerate() {
		let Some((features, rows, bytes)) = nearest else { continue };
		// A node whose arithmetic cannot tell a large value from zero builds no index.
		if node.precision.pack(f64::MAX) == node.precision.pack(0.0) {
			continue;
		}
		// The node's weights, read back from its own span in its own type.
		let effective = weights.download_float_bytes(layout.weights[index], rows * features, node.precision)?;
		let mut region = vec![0_u8; bytes];
		NearestIndex::build(&effective, features, rows).write(&mut region);
		regions.push((layout.contexts[index], region));
	}
	Ok(regions)
}
impl NativeTape {
	fn llvm_report(&self) -> LlvmReport {
		LlvmReport {
			instructions: NameList::new(self.program.artifact.llvm.instructions.clone()),
			intrinsics: NameList::new(self.program.artifact.llvm.intrinsics.clone()),
		}
	}
	fn format_lines(&self) -> Result<Vec<String>> {
		let device = self.device_label()?;
		let mut lines = Vec::new();
		let mut seen = std::collections::BTreeSet::new();
		for (index, node) in self.nodes.iter().enumerate() {
			let storage = &self.storage[index];
			let operand = if node.int_bits == 32 { "fp32".to_owned() } else if node.int_bits != 0 { format!("int{}", node.int_bits) } else { node.precision.label() };
			let cache = if node.op == Primitive::Attention { format!(" KV storage {}", node.kv_precision.label()) } else { String::new() };
			let item = format!("{} {} storage {storage} operand {operand} accumulator {} result {}{cache}", node.block_kind, node.primitive_name(), node.acc.label(), node.precision.label());
			if seen.insert(item.clone()) { lines.push(format!("{device}  format: {item}")); }
		}
		Ok(lines)
	}
	fn memory_line(&self) -> Result<String> {
		let (input, output) = self.request_bytes();
		Ok(format!(
			"{}  memory: input {} bytes weights {} bytes values {} bytes contexts {} bytes adjoints {} bytes gradients {} bytes optimizer {} bytes load-scratch {} bytes",
			self.device_label()?,
			self.samples.bytes + input,
			self.weights.bytes,
			self.values.bytes + output,
			self.contexts.bytes,
			self.adjoints.bytes,
			self.gradient.bytes,
			self.moments.bytes + self.variances.bytes,
			self.program.artifact.storage.bytes
		))
	}
	fn tile_lines(&self) -> Result<Vec<String>> {
		let device = self.device_label()?;
		Ok(self
			.program
			.schedule
			.contractions
			.iter()
			.enumerate()
			.filter_map(|(index, tiles)| tiles.map(|tiles| if self.program.epoch.is_some() {
				format!("{device}  tile: {} fwd {}x{}x{} wgd {}x{}x{} igd {}x{}x{}", self.nodes[index].identity(index), tiles.forward.m, tiles.forward.n, tiles.forward.k, tiles.gradient.m, tiles.gradient.n, tiles.gradient.k, tiles.previous.m, tiles.previous.n, tiles.previous.k)
			} else {
				format!("{device}  tile: {} pp {}x{}x{}", self.nodes[index].identity(index), tiles.forward.m, tiles.forward.n, tiles.forward.k)
			}))
			.chain(self.program.schedule.attention.iter().enumerate().filter_map(|(index, extent)| extent.map(|extent| {
				format!("{device}  tile: {} attention {}x{}x{}", self.nodes[index].identity(index), extent.m, extent.n, extent.k)
			})))
			.collect())
	}
	fn grid_lines(&self) -> Result<Vec<String>> {
		let device = self.device_label()?;
		let mut lines = Vec::new();
		let forward = self.program.forward.geometry;
		if let Some(epoch) = self.program.epoch {
			lines.push(format!("{device}  grid: forward {}x1x1 workgroup {}x1x1", forward.groups, forward.block));
			lines.push(format!("{device}  grid: epoch {}x1x1 workgroup {}x1x1", epoch.geometry.groups, epoch.geometry.block));
		} else {
			lines.push(format!("{device}  grid: pp {}x1x1 workgroup {}x1x1", forward.groups, forward.block));
			if let Some(tg) = self.program.step_geometry() {
				lines.push(format!("{device}  grid: tg {}x1x1 workgroup {}x1x1", tg.groups, tg.block));
			}
		}
		if let Some(load) = self.program.model_load { lines.push(format!("{device}  grid: load {}x1x1 workgroup {}x1x1", load.geometry.groups, load.geometry.block)); }
		let mut dispatches = vec![("forward", self.program.forward)];
		#[cfg(nvidia)]
		if let NativeBackend::Nvidia(program) = &self.program.backend && let Some(step) = program.step { dispatches.push(("tg", step)); }
		if let Some(epoch) = self.program.epoch { dispatches.push(("epoch", epoch)); }
		for (entry, dispatch) in dispatches {
			if let Some((registers, local)) = dispatch.kernel.nvidia_resources {
				lines.push(format!("{device}  resources: {entry} registers/thread {registers} local-bytes/thread {local}"));
			}
		}
		Ok(lines)
	}
	/// `tokens` are the model's ids, one per position of every row, which the
	/// lookups of this graph gather rows for; a whole graph reads its own
	/// samples, and a part of a split graph reads the ids its stream came from.
	fn new(graph: &Graph, samples: TapeInput<'_>, tokens: &[f64], targets: &[f64], gpu: &'static Gpu, precision: Compute, loss: Option<LossFunction>) -> Result<Self> {
		let prepare_started = Instant::now();
		let training_graph;
		let graph = if loss.is_some() {
			training_graph = graph.training_graph()?;
			training_graph.as_ref()
		} else { graph };
		let precision = if loss.is_some() && graph.profile.train == Some(Compute::FP64) && graph.nodes.iter().any(|node| node.int_bits != 0) { Compute::FP64 } else { precision };
		let input = graph.input.elements();
		require(input != 0 && samples.len() != 0 && samples.len() % input == 0, format!("model input batch expected a nonempty multiple of {input} {}, received {}", samples.label(), samples.len()))?;
		let rows = samples.len() / input;
		let output = graph.output.elements();
		require(targets.is_empty() || targets.len() == rows * output, format!("target batch expected 0 or {} values, received {}", rows * output, targets.len()))?;
		let inference = loss.is_none();
		// Forward-only estimator prefixes preserve training semantics without an unused epoch entry.
		let epoch = loss.is_some() && !targets.is_empty();
		let program = gpu.native_program(graph, rows, precision, loss, epoch)?;
		let mut resolutions = std::collections::BTreeSet::new();
		for node in &graph.nodes {
			let format = ContractFormat::of(node.precision, node.int_bits)?;
			let capability = resolve_capability(&gpu.native_target, format)?;
			let native = NativePrecision::new(node.precision, node.acc)?;
			let route = if node.op == Primitive::Contraction && program.schedule.matrix && matrix_capable(native) {
				capability.matrix.map(|(_, name)| name).or(capability.vector).unwrap_or("none")
			} else { capability.vector.or(capability.matrix.map(|(_, name)| name)).unwrap_or("none") };
			let storage = if node.int_bits == 4 { "q4_1" } else if node.int_bits != 0 { "q8_0" } else { "file" };
			let detail = if node.int_bits != 0 && inference {
				format!("; {storage} weights, {} activations", if node.int_bits == 32 { "unchanged fp32".to_owned() } else { format!("int{}", node.int_bits) })
			} else if node.int_bits != 0 {
				format!("; {} training, {} gradients, {} optimizer, {storage} checkpoint", node.precision.label(), native.state.label(), NativePrecision::new(precision, graph.profile.acc)?.state.label())
			} else { String::new() };
			let line = format!("{} {} -> {route}{detail}", node.block_kind, format.name());
			if resolutions.insert(line.clone()) { trace(&format!("route {line}"))?; }
		}
		let (precision, layout, parameters) = (program.artifact.precision, program.artifact.layout.clone(), graph.parameters.len());
		// Only the epoch entrypoint reads the optimizer state, the gradient and
		// the adjoints, so an inference tape holds none of them on the device.
		let training = program.artifact.training;
		let state_values = if training { parameters.max(1) } else { 1 };
		let zeros = vec![0.0; state_values];
		let gradient_bytes = if training { program.gradient_bytes.max(1) } else { 1 };
		require(graph.state.moments.is_empty() || graph.state.moments.len() == parameters, "saved optimizer moments have the wrong shape")?;
		require(graph.state.variances.is_empty() || graph.state.variances.len() == parameters, "saved optimizer variances have the wrong shape")?;
		require(graph.frozen.is_empty() || graph.frozen.len() == parameters, "frozen parameters have the wrong shape")?;
		let moments = if training && !graph.state.moments.is_empty() { graph.state.moments.clone() } else { zeros.clone() };
		let variances = if training && !graph.state.variances.is_empty() { graph.state.variances.clone() } else { zeros.clone() };
		let frozen_mask = if training && !graph.frozen.is_empty() { graph.frozen.clone() } else { vec![0_u8; state_values] };
		let batch_normalizations = saved_statistics(&graph.nodes, rows)?;
		let best_loss = if graph.state.best_loss.is_empty() {
			[f64::INFINITY, f64::NAN, f64::NAN, f64::INFINITY]
		} else {
			graph.state.best_loss.as_slice().try_into().map_err(|_| RecipeError::new("saved loss state is invalid"))?
		};
		let step = narrow(graph.state.epoch, "optimizer epoch")? as u32;
		let target_buffer = if targets.is_empty() { vec![0.0] } else { targets.to_vec() };
		let adjoints_bytes = if training { layout.adjoints_bytes.max(1) } else { 1 };
		let input_adjoint_bytes = if training { checked_mul(samples.len(), layout.input_adjoint_precision.bytes(), "native input adjoint allocation")?.max(1) } else { 1 };
		// A graph that starts with a gather reads its input as i32 token ids.
		let vocabulary = graph.nodes.first().filter(|node| node.token_input()).map_or(0.0, |node| node.argument[0]);
		let token_count = tokens.len();
		let tokens = Mutex::new(tokens.to_vec());
		let samples = match (samples, vocabulary > 0.0) {
			(TapeInput::Zeroed(count), ids) => {
				let count = if layout.request_control.is_some() { checked_mul(graph.input.channels, layout.window_positions, "initial input window")? } else { count };
				Buffer::zeroed(gpu, checked_mul(count, if ids { size_of::<i32>() } else { layout.input_precision.bytes() }, "initial input bytes")?)?
			}
			(TapeInput::Ids(ids), true) => {
				let ids = ids.iter().map(|id| require(f64::from(*id) < vocabulary, format!("token id {id} is outside the vocabulary of {vocabulary}")).map(|()| *id as i32)).collect::<Result<Vec<_>>>()?;
				Buffer::upload(gpu, &ids)?
			}
			(TapeInput::Ids(_), false) => return Err(RecipeError::new("token ids need a model whose first block is an embedding")),
			(TapeInput::Values(values), true) => Buffer::upload(gpu, &values.iter().map(|id| token_id(*id, vocabulary)).collect::<Result<Vec<_>>>()?)?,
			(TapeInput::Values(values), false) => Buffer::upload_float(gpu, values, layout.input_precision)?,
		};
		let (weight_offsets, weight_bytes) = native_weight_arena(graph, precision.model, inference)?;
		let weight_key = weight_arena_key(gpu, graph, precision.model, inference, &weight_offsets, weight_bytes);
		let (weights, attached) = resident_arena(gpu, weight_key, weight_bytes, |weights| weights.fill_weights(graph, precision.model, inference))?;
		if let Some(execution) = &graph.expert_execution {
			let execution = execution.lock().map_err(|_| RecipeError::new("expert execution is poisoned"))?;
			let (offsets, _) = native_weight_arena(graph, precision.model, true)?;
			for layer in &graph.expert_layers { weights.write_bytes(offsets[layer.node], &execution.main_descriptors[layer.global].pointer.to_ne_bytes())?; }
		}
		// An attached arena already holds what the load kernel writes.
		if program.model_load.is_some() && !attached {
			let image = &program.artifact.storage;
			require(!image.is_empty(), "native model-load storage is empty")?;
			// One node at a time through one scratch the size of the largest
			// source, so the file's bytes never sit whole beside the weights.
			let storage = Buffer::reserve(gpu, image.bytes)?;
			let threads = program.dispatch(NativeEntry::ModelLoad)?.geometry.threads()?;
			for (node, stored) in &image.segments {
				if tracing() { trace(&format!("load write node {node} bytes {}", stored.len()))?; }
				storage.write_runs(0, stored)?;
				let index = i32::try_from(*node).map_err(|_| RecipeError::new("native model-load node index exceeds i32"))?;
				if tracing() { trace(&format!("load dispatch node {node} bytes {} threads {threads}", stored.len()))?; }
				let mut call = ptrs![weights.pointer, storage.pointer, threads, index];
				program.launch_model_load(&mut call)?;
				gpu.synchronize()?;
				if tracing() { trace(&format!("load synced node {node}"))?; }
				// A traced run compares the first values the load wrote against the
				// host's own decode of the same bytes.
				if tracing() && let Some(Some(weight)) = graph.stored.get(*node) && let Some(spec) = weight.format.spec() {
					let (offsets, _) = native_weight_arena(graph, precision.model, inference)?;
					// A packed node's first block comes back as bytes and decodes on the host.
					let written = if graph.nodes[*node].packed {
						let bytes = weights.download_range::<u8>(offsets[*node], spec.stride.min(weight.bytes.len()))?;
						let mut values = weight.format.decompress(&bytes, &weight.codebook, spec.block.min(weight.count))?;
						values.truncate(8);
						values
					} else {
						weights.download_float_bytes(offsets[*node], spec.block.min(weight.count).min(8), graph.nodes[*node].precision)?
					};
					// The host reference is the file's own bytes: the requantize source when there is one.
					let reference = graph.requantize.get(*node).and_then(Option::as_ref).unwrap_or(weight);
					let host = reference.segments.first().and_then(|(span, _)| span.spec().map(|first| (span, first))).map(|(span, first)| stored_first_values(reference, *span, first.stride, first.block)).transpose()?.unwrap_or_default();
					let raw = weights.download_range::<u8>(offsets[*node], 16)?;
					trace(&format!("load node {node} {} wrote {written:?} machine {host:?} bytes {raw:02x?} offset {}", quantization(weight.format.0), offsets[*node]))?;
				}
			}
		} else {
			require(program.artifact.storage.is_empty(), "native artifact storage has no model-load entrypoint")?;
		}
		// The arenas are cleared on the device rather than staged whole on the
		// host: a later position reads the zeros the earlier windows left.
		// RECIPE_ARENA_GUARD=bytes pads every arena on both sides by that many
		// zeroed bytes: a kernel that writes past its region then lands in the
		// guard, not the next arena.
		let guard = std::env::var("RECIPE_ARENA_GUARD").ok().and_then(|text| text.parse::<usize>().ok()).unwrap_or(0);
		let values = Buffer::zeroed_guarded(gpu, layout.values_bytes, guard)?;
		let contexts = Buffer::zeroed_guarded(gpu, layout.contexts_bytes, guard)?;
		// Inference tables keep their packed mappings in machine RAM. Each request
		// stages only its addressed rows; training retains the device gather table.
		let (mut lookups, positions) = (Vec::new(), graph_positions(graph));
		for (index, node) in graph.nodes.iter().enumerate() {
			if inference && node.op == Primitive::Gather {
				let table = hold_host_table(graph.stored.get(index).and_then(Option::as_ref).ok_or_else(|| RecipeError::new("embedding table is absent"))?.clone())?;
				lookups.push(HostLookup { context: layout.contexts[index], precision: node.precision, hash: None, table, width: node.argument[1] as usize, length: node.output.length });
			} else if node.op == Primitive::Gather {
				let table = graph.stored.get(index).and_then(Option::as_ref).ok_or_else(|| RecipeError::new("embedding table is absent"))?;
				let at = layout.contexts[index];
				require(checked_add(at, table.bytes.len(), "embedding table context")? <= contexts.bytes, "embedding table exceeds its context arena")?;
				for (offset, run) in table.bytes.runs() {
					contexts.write_bytes(at + offset, run)?;
				}
			}
			if node.op == Primitive::Lookup {
				let table = hold_host_table(graph.stored.get(index).and_then(Option::as_ref).ok_or_else(|| RecipeError::new("per-layer embedding table is absent"))?.clone())?;
				let words = graph.programs.get(node.program_offset..node.program_offset + node.program_count * 3).ok_or_else(|| RecipeError::new("per-layer embedding hash is absent"))?;
				require(node.output.length == positions, format!("per-layer embedding reads {} positions of {positions} ids", node.output.length))?;
				require(token_count == rows * positions, format!("per-layer embedding reads {} ids for {rows} rows of {positions} positions, received {token_count}", rows * positions))?;
				lookups.push(HostLookup { context: layout.contexts[index], precision: node.precision, hash: Some(RowHash::from_words(words)?), table, width: node.argument[1] as usize, length: node.output.length });
			}
		}
		let context_resets = layout.context_resets.clone();
		for (offset, region) in native_context_regions(graph, &layout, &weights, precision.model)? {
			require(checked_add(offset, region.len(), "nearest index context")? <= contexts.bytes, "nearest index exceeds its context arena")?;
			contexts.write_bytes(offset, &region)?;
		}
		for (index, node) in graph.nodes.iter().enumerate() {
			if let Some(rope) = rope_sections(node, &graph.programs)? {
				contexts.write_bytes(layout.contexts[index], &rope_context_region(rope, rows, node.output.length, None)?)?;
			}
		}
		trace(&format!(
			"native tape device={} mode={} rows={rows} values={} contexts={} weights={} adjoints={adjoints_bytes}",
			gpu.name,
			if inference { "inference" } else { "training" },
			values.bytes,
			contexts.bytes,
			weights.bytes
		))?;
		write_contraction_schedule(&contexts, &layout, &program.schedule.contractions)?;
		let compile_seconds = program.artifact.compile_seconds;
		let load_seconds = (prepare_started.elapsed().as_secs_f64() - compile_seconds).max(0.0);
		let storage = graph.nodes.iter().enumerate().map(|(index, node)| {
			if node.weights() == 0 { return "none".to_owned(); }
			let Some(weight) = graph.stored.get(index).and_then(Option::as_ref).filter(|_| node.packed || node.table()) else { return node.precision.label(); };
			let mut formats = Vec::new();
			for (format, _) in weight.format_segments() {
				let format = if format.0 == 0 { node.precision.label() } else { quantization(format.0) };
				if !formats.contains(&format) { formats.push(format); }
			}
			formats.join("+")
		}).collect();
		let tape = Self {
			expert_execution: graph.expert_execution.clone(),
			expert_first: graph.expert_layers.first().map_or(0, |layer| layer.global),
			expert_count: graph.expert_layers.len(),
			observations: graph.observations,
			tensor_history: Mutex::new(Vec::new()),
			profile: graph.profile,
			program,
			precision,
			values,
			contexts,
			context_resets,
			lookups,
			lookup_rows: (inference && graph.expert_execution.is_some()).then(|| Mutex::new(LookupRows::default())),
			tokens,
			adjoints: Buffer { runtime: gpu, pointer: gpu.allocate(adjoints_bytes)?, bytes: adjoints_bytes },
			batch_normalizations,
			samples,
			request: Mutex::new(None),
			saved_output: Mutex::new(Vec::new()),
			input_adjoint: Buffer { runtime: gpu, pointer: gpu.allocate(input_adjoint_bytes)?, bytes: input_adjoint_bytes },
			targets: Buffer::upload_float(gpu, &target_buffer, layout.output_precision)?,
			weights,
			frozen: Buffer::upload(gpu, &frozen_mask)?,
			moments: Buffer::upload_float(gpu, &moments, precision.state)?,
			variances: Buffer::upload_float(gpu, &variances, precision.state)?,
			gradient: Buffer::zeroed(gpu, gradient_bytes)?,
			metrics: Buffer::zeroed(gpu, EpochMetrics::VALUES * layout.output_adjoint_precision.bytes())?,
			best_loss,
			rows: narrow(rows, "native rows")? as u32,
			parameters,
			step,
			input: graph.input,
			output: graph.output,
			nodes: graph.nodes.clone(),
			programs: graph.programs.clone(),
			storage,
			capacity: rows,
			positions: narrow(positions, "native input positions")? as u32,
			vocabulary,
			compile_seconds,
			load_seconds,
			last_device_seconds: AtomicU64::new(0.0_f64.to_bits()),
			operations: Mutex::new(Vec::new()),
			reached: std::sync::atomic::AtomicU32::new(0),
			window_begin: std::sync::atomic::AtomicU32::new(0),
		};
		Ok(tape)
	}
	/// Writes every contraction node's forward, gradient, and previous tiles
	/// into its schedule slot, where the kernels read them at dispatch.
	fn write_schedule(&self) -> Result<()> {
		write_contraction_schedule(&self.contexts, &self.program.artifact.layout, &self.program.schedule.contractions)
	}
	/// Commit cached indexer sums at an accepted prefix without another model
	/// invocation. Preflight every span before changing the saved image. The
	/// caller restores the image with its other accepted state and poisons the
	/// transaction if restoration fails.

	/// Applies a runtime contraction schedule to both the host description and
	/// the words read by the native kernels.
	fn apply_contraction_schedule(&mut self, contractions: Vec<Option<NativeContractionTiles>>) -> Result<()> {
		require(contractions.len() == self.program.schedule.contractions.len(), "native contraction schedule assignment has the wrong shape")?;
		self.program.schedule.contractions = contractions;
		self.write_schedule()?;
		self.program.tile = dominant_tile(&self.program.shapes, &self.program.schedule.contractions).unwrap_or(self.program.tile);
		Ok(())
	}
	/// Every mutable device buffer and host-side training field. A schedule
	/// measurement restores this complete state before every launch.
	fn snapshot_state(&self) -> Result<NativeTrainingState> {
		Ok(NativeTrainingState {
			values: self.values.download(self.values.bytes)?,
			contexts: self.contexts.download(self.contexts.bytes)?,
			adjoints: self.adjoints.download(self.adjoints.bytes)?,
			input_adjoint: self.input_adjoint.download(self.input_adjoint.bytes)?,
			weights: self.weights.download(self.weights.bytes)?,
			frozen: self.frozen.download(self.frozen.bytes)?,
			moments: self.moments.download(self.moments.bytes)?,
			variances: self.variances.download(self.variances.bytes)?,
			gradient: self.gradient.download(self.gradient.bytes)?,
			metrics: self.metrics.download(self.metrics.bytes)?,
			contractions: self.program.schedule.contractions.clone(),
			tile: self.program.tile,
			step: self.step,
			best_loss: self.best_loss,
		})
	}
	fn restore_state(&mut self, state: &NativeTrainingState) -> Result<()> {
		self.values.write_bytes(0, &state.values)?;
		self.contexts.write_bytes(0, &state.contexts)?;
		self.adjoints.write_bytes(0, &state.adjoints)?;
		self.input_adjoint.write_bytes(0, &state.input_adjoint)?;
		self.weights.write_bytes(0, &state.weights)?;
		self.frozen.write_bytes(0, &state.frozen)?;
		self.moments.write_bytes(0, &state.moments)?;
		self.variances.write_bytes(0, &state.variances)?;
		self.gradient.write_bytes(0, &state.gradient)?;
		self.metrics.write_bytes(0, &state.metrics)?;
		self.program.schedule.contractions.clone_from(&state.contractions);
		self.program.tile = state.tile;
		self.step = state.step;
		self.best_loss = state.best_loss;
		self.write_schedule()
	}
	/// Returns the exact persistent post-epoch state relevant to repeatability.
	/// Activations, adjoints, gradients, metrics, and other fused-epoch scratch
	/// are restored before every measurement but are overwritten by the next
	/// epoch, so they are not part of semantic schedule equivalence.
	fn epoch_state(&self, objective: f64) -> Result<NativeEpochState> {
		Ok(NativeEpochState {
			input_adjoint: self.input_adjoint.download(self.input_adjoint.bytes)?,
			weights: self.weights.download(self.weights.bytes)?,
			frozen: self.frozen.download(self.frozen.bytes)?,
			moments: self.moments.download(self.moments.bytes)?,
			variances: self.variances.download(self.variances.bytes)?,
			batch_normalizations: self.extract_bn_stats()?.into_iter().map(f64::to_bits).collect(),
			best_loss: self.best_loss.map(f64::to_bits),
			step: self.step,
			objective: objective.to_bits(),
		})
	}
	fn forward(&self, mode: ForwardMode) -> Result<()> {
		if self.program.artifact.layout.request_control.is_some() {
			self.prepare_request(0, self.positions)?;
			let request = self.request.lock().map_err(|_| RecipeError::new("request buffers are poisoned"))?;
			let request = request.as_ref().ok_or_else(|| RecipeError::new("request input was not prepared"))?;
			require(request.input.bytes <= self.samples.bytes, "initial input does not cover the request")?;
			request.input.write_bytes(0, &self.samples.download(request.input.bytes)?)?;
		}
		self.forward_window(0, self.positions, mode)
	}
	fn prepare_request(&self, begin: u32, end: u32) -> Result<()> {
		let layout = &self.program.artifact.layout;
		if layout.request_control.is_none() { return Ok(()) }
		require(begin <= end && end <= self.positions, "request window is outside the context")?;
		let mut state = self.request.lock().map_err(|_| RecipeError::new("request buffers are poisoned"))?;
		if state.is_none() { *state = Some(NativeRequest::new(self.program.gpu)?); }
		let request = state.as_mut().unwrap();
		let positions = (end - begin) as usize;
		let input_bytes = if self.vocabulary > 0.0 { size_of::<i32>() } else { layout.input_precision.bytes() };
		NativeRequest::grow(&mut request.input, checked_mul(checked_mul(self.input.channels, positions, "request input elements")?, input_bytes, "request input bytes")?)?;
		let output_positions = if self.output.length == 1 { 1 } else { positions };
		NativeRequest::grow(&mut request.output, checked_mul(checked_mul(self.output.channels, output_positions, "request output elements")?, layout.output_precision.bytes(), "request output bytes")?)?;
		if let Some((index, node)) = self.nodes.iter().enumerate().find(|(_, node)| node.retain_output) {
			NativeRequest::grow(&mut request.hidden, checked_mul(checked_mul(node.output.channels, positions, "request hidden elements")?, layout.precisions[index].bytes(), "request hidden bytes")?)?;
		}
		request.begin = begin;
		request.positions = positions;
		Ok(())
	}
	/// The id one input value names.
	fn token(&self, value: f64) -> Result<u32> {
		if self.vocabulary > 0.0 {
			return token_id(value, self.vocabulary).map(|id| id as u32);
		}
		require(value.fract() == 0.0 && value >= 0.0 && value <= f64::from(u32::MAX), format!("input value {value} is not a token id"))?;
		Ok(value as u32)
	}
	/// Gather every lookup's rows for the positions `begin..end` of every row on
	/// the host and write them into the staging context the device reads.
	fn stage_lookups(&self, begin: u32, end: u32, mut request: Option<&mut NativeRequest>) -> Result<()> {
		let (begin, end) = (begin as usize, end as usize);
		let tokens = self.tokens.lock().map_err(|_| RecipeError::new("token state is poisoned"))?;
		let mut cache = self.lookup_rows.as_ref().map(|cache| cache.lock().map_err(|_| RecipeError::new("lookup row cache is poisoned"))).transpose()?;
		for (index, lookup) in self.lookups.iter().enumerate() {
			let bytes = lookup.precision.bytes();
			let channels = lookup.hash.as_ref().map_or(1, RowHash::heads) * lookup.width;
			let (buffer, base, length, first) = if let Some(request) = request.as_mut() {
				if index == request.lookups.len() { request.lookups.push(Buffer::zeroed(self.program.gpu, 1)?); }
				let buffer = &mut request.lookups[index];
				NativeRequest::grow(buffer, checked_mul(checked_mul(end - begin, channels, "lookup request elements")?, bytes, "lookup request bytes")?)?;
				self.contexts.write_bytes(lookup.context, &buffer.pointer.to_ne_bytes())?;
				(&*buffer, 0, end - begin, 0)
			} else { (&self.contexts, lookup.context, lookup.length, begin) };
			for row in 0..self.rows as usize {
				let ids = tokens[row * lookup.length..(row + 1) * lookup.length].iter().map(|value| self.token(*value)).collect::<Result<Vec<_>>>()?;
				let mut staged = Vec::with_capacity((end - begin) * channels);
				for position in begin..end {
					if let Some(hash) = &lookup.hash {
						for row in hash.rows_at(&ids, position) {
							if let Some(cache) = cache.as_mut() { cache.append(index, lookup, row, &mut staged)?; }
							else { staged.extend(ngram::table_row(&lookup.table, lookup.width, row)?); }
						}
					} else {
						let row = ids[position] as usize;
						if let Some(cache) = cache.as_mut() { cache.append(index, lookup, row, &mut staged)?; }
						else { staged.extend(ngram::table_row(&lookup.table, lookup.width, row)?); }
					}
				}
				let slot = checked_mul(checked_add(checked_mul(row, length, "lookup row")?, first, "lookup slot")?, channels, "lookup staging offset")?;
				buffer.write_float_bytes(checked_add(base, checked_mul(slot, bytes, "lookup staging bytes")?, "lookup staging")?, &staged, lookup.precision)?;
			}
		}
		Ok(())
	}
	/// Write the output positions that the input positions before `end` reach and
	/// that the input positions before `begin` did not. The arenas keep every
	/// earlier position, so a step reads the attention keys and values, the
	/// recurrent state, and the convolution tail that earlier calls left.
	fn forward_window(&self, begin: u32, end: u32, mode: ForwardMode) -> Result<()> {
		self.forward_window_with_samples(self.samples.pointer, begin, end, mode)
	}
	fn forward_window_with_samples(&self, samples: u64, begin: u32, end: u32, mode: ForwardMode) -> Result<()> {
		self.forward_window_observed(samples, begin, end, mode, &mut |_, _| {})
	}
	fn forward_window_observed(&self, samples: u64, begin: u32, end: u32, mode: ForwardMode, observed: &mut dyn FnMut(u32, f64)) -> Result<()> {
		require(begin <= end && end <= self.positions, format!("forward window {begin}..{end} is outside the {} input positions", self.positions))?;
		let mut request = self.request.lock().map_err(|_| RecipeError::new("request buffers are poisoned"))?;
		let samples = if let Some(control) = self.program.artifact.layout.request_control {
			let request = request.as_ref().ok_or_else(|| RecipeError::new("request input was not prepared"))?;
			require(request.begin == begin && request.positions == (end - begin) as usize, "prepared request does not match the execution window")?;
			let mut record = [0_u8; 24];
			record[..4].copy_from_slice(&begin.to_ne_bytes());
			record[4..8].copy_from_slice(&(end - begin).to_ne_bytes());
			record[8..16].copy_from_slice(&request.output.pointer.to_ne_bytes());
			record[16..].copy_from_slice(&request.hidden.pointer.to_ne_bytes());
			self.contexts.write_bytes(control, &record)?;
			request.input.pointer
		} else { samples };
		let capacity = self.program.artifact.layout.window_positions as u32;
		self.reached.store(end, Ordering::Relaxed);
		let retained_begin = if begin < end { begin + (end - begin - 1) / capacity * capacity } else { begin };
		self.window_begin.store(retained_begin, Ordering::Relaxed);
		self.stage_lookups(begin, end, request.as_mut())?;
		if let Some(clocks) = self.program.artifact.layout.clocks {
			self.contexts.clear_range(clocks, self.nodes.len() * 24)?;
		}
		if let Some(offset) = self.program.artifact.layout.packed_routes {
			self.contexts.clear_range(offset, self.nodes.len() * 20)?;
		}
		let threads = self.program.forward.geometry.threads()?;
		let rows = self.rows;
		let mut thread_count = threads;
		let single = matches!(mode, ForwardMode::Inference | ForwardMode::StateOnly) && end - begin == 1;
		#[cfg(amd)]
		if single && let NativeBackend::Amd(program) = &self.program.backend && let Some(dispatch) = program.step { thread_count = dispatch.geometry.threads()?; }
		#[cfg(nvidia)]
		if single && let NativeBackend::Nvidia(program) = &self.program.backend && let Some(dispatch) = program.step { thread_count = dispatch.geometry.threads()?; }
		let mode = mode as i32;
		let mut call = ptrs![samples, self.weights.pointer, self.values.pointer, self.contexts.pointer, rows, thread_count, begin, end, mode];
		let machine_started = Instant::now();
		let mut expert_guard = self.expert_execution.as_ref().map(|execution| execution.lock().map_err(|_| RecipeError::new("expert execution is poisoned"))).transpose()?;
		let expert_count = if mode == ForwardMode::StateOnly as i32 && expert_guard.as_ref().is_some_and(|execution|
			execution.layers.get(self.expert_first + self.expert_count.saturating_sub(1)).is_some_and(|layer| layer.node + 1 == self.nodes.len()))
		{ self.expert_count.saturating_sub(1) } else { self.expert_count };
		if let Some(execution) = expert_guard.as_mut() { execution.start(self.expert_first, expert_count, begin, end, capacity)?; }

		if let Err(error)=self.program.launch_forward(&mut call,single).and_then(|_|self.program.gpu.synchronize()) {
			if let Some(execution)=expert_guard.as_mut() {execution.abort();} return Err(RecipeError::new(format!("forward: {error}")));
		}
		let mut records = Vec::with_capacity(3);
		if let Some(execution)=expert_guard.as_mut() {
			match execution.finish(self.expert_first,expert_count,begin,end,capacity) {
				Ok(record)=>records.push(record),
				Err(error)=>{execution.abort();return Err(error);},
			}
		}
		drop(expert_guard);
		let ticks = self.contexts.download_range::<i64>(self.program.artifact.layout.timing / 8, 2)?;
		let seconds = if self.program.gpu.backend == Backend::Cpu { machine_started.elapsed().as_secs_f64() } else { ticks[1].wrapping_sub(ticks[0]).max(0) as f64 / 1e9 };
		self.last_device_seconds.store(seconds.to_bits(), Ordering::Release);
		observed(end, seconds);
		records.push(OperationRecord::Report(OperationReport {
			device: self.device_label()?, model: String::new(), block: 0, node: usize::MAX, operation: "ForwardWindow".to_owned(), begin, end,
			positions: (end - begin) as usize, ticks: ticks[1].wrapping_sub(ticks[0]).max(0) as u64,
			seconds: (self.program.gpu.backend != Backend::Cpu).then_some(seconds), selected_experts: 0, weight_bytes: 0, packed_calls: 0,
			packed_fallbacks: [0; 4], span_calls: 0, fingerprints: Vec::new(), cache_fingerprints: Vec::new(), cache_channel_fingerprints: Vec::new(),
		}));
		if mode == ForwardMode::Inference as i32 && self.observations != 0 {
			let tensors = self.capture_tensors(begin, end)?;
			self.tensor_history.lock().map_err(|_| RecipeError::new("tensor observation history is poisoned"))?.extend(tensors);
		}
		if let Some(clocks) = self.program.artifact.layout.clocks {
			let clocks = self.contexts.download_range::<u64>(clocks / 8, self.nodes.len() * 3)?;
			let fingerprints = if let Some(offset) = self.program.artifact.layout.fingerprints.filter(|_| begin < end) {
				let first = if capacity < self.positions { 0 } else { retained_begin as usize };
				self.contexts.download_range::<u64>(offset / 8 + first * self.nodes.len(), (end - retained_begin) as usize * self.nodes.len())?
			} else { Vec::new() };
			let cache_begin = end.saturating_sub(capacity);
			let cache_fingerprints = if let Some(offset) = self.program.artifact.layout.fingerprints.filter(|_| begin < end) {
				self.contexts.download_range::<u64>(offset / 8 + capacity as usize * self.nodes.len(), (end - cache_begin) as usize * self.nodes.len())?
			} else { Vec::new() };
			let packed_routes = if let Some(offset) = self.program.artifact.layout.packed_routes {
				self.contexts.download_range::<u32>(offset / 4, self.nodes.len() * 5)?
			} else { Vec::new() };
			let mut cache_channels = Vec::new();
			for (index, (node, clocks)) in self.nodes.iter().zip(clocks.chunks_exact(3)).enumerate() {
				let Some(offset) = self.program.artifact.layout.cache_channel_fingerprints[index].filter(|_| clocks[2] != 0) else { continue };
				let channels = attention_kv_bytes(node, 1, node.kv_precision)? / node.output.length / node.kv_precision.bytes();
				cache_channels.push((index, self.contexts.download_range::<u64>(offset / 8, channels)?.into_iter().enumerate().map(|(channel, hash)| (channel as u32, hash)).collect()));
			}
			records.push(OperationRecord::Nodes { begin, end, retained_begin, cache_begin, clocks, fingerprints, cache_fingerprints, packed_routes, cache_channels });
		}
		self.operations.lock().map_err(|_| RecipeError::new("operation reports are poisoned"))?.extend(records);
		Ok(())
	}
	/// Report rows for every window since the last call, built from the raw measurements each window kept.
	fn take_operations(&self) -> Result<Vec<OperationReport>> {
		let records = std::mem::take(&mut *self.operations.lock().map_err(|_| RecipeError::new("operation reports are poisoned"))?);
		let device = self.device_label()?;
		let mut operations = Vec::new();
		for record in records {
			match record {
				OperationRecord::Report(report) => operations.push(report),
				OperationRecord::Experts { first, layers, begin, end, capacity, receipts, trace } => {
					let execution = self.expert_execution.as_ref().ok_or_else(|| RecipeError::new("expert receipts have no execution"))?;
					execution.lock().map_err(|_| RecipeError::new("expert execution is poisoned"))?.observations(first, layers, begin, end, capacity, receipts, &trace, &mut operations)?;
				}
				OperationRecord::Nodes { begin, end, retained_begin, cache_begin, clocks, fingerprints, cache_fingerprints, packed_routes, mut cache_channels } => {
					for (index, (node, clocks)) in self.nodes.iter().zip(clocks.chunks_exact(3)).enumerate() {
						if clocks[2] == 0 { continue; }
						let routes = packed_routes.get(index * 5..index * 5 + 5).unwrap_or(&[0; 5]);
						let cache_channel_fingerprints = cache_channels.iter_mut().find(|(node, _)| *node == index).map(|(_, hashes)| std::mem::take(hashes)).unwrap_or_default();
						operations.push(OperationReport {
							selected_experts:0, weight_bytes:0,
							device: device.clone(), model: String::new(), block: node.block_index, node: index,
							operation: node.primitive_name().to_owned(), begin, end, positions: clocks[2] as usize, ticks: clocks[1],
							packed_calls: routes[0] as usize,
							packed_fallbacks: [routes[1] as usize, routes[2] as usize, routes[3] as usize, routes[4] as usize], span_calls: 0,
							seconds: (self.program.gpu.backend != Backend::Cpu).then_some(clocks[1] as f64 / 1e9),
							fingerprints: fingerprints.chunks_exact(self.nodes.len()).enumerate().filter_map(|(row, hashes)| {
								let position = retained_begin + row as u32;
								(node.output.length == self.input.length || node.output.length == 1 && position + 1 == end).then_some((position, hashes[index]))
							}).collect(),
							cache_fingerprints: if node.op == Primitive::Attention {
								cache_fingerprints.chunks_exact(self.nodes.len()).enumerate().map(|(row, hashes)| (cache_begin + row as u32, hashes[index])).collect()
							} else { Vec::new() },
							cache_channel_fingerprints,
						});
					}
				}
			}
		}
		Ok(operations)
	}
	/// Evaluate rows after `first` with this trained native program. The input
	/// buffer is reused in bounded chunks, and `%rows` changes per launch, so a
	/// holdout does not compile a second artifact or read stale rows.
	fn evaluate(&mut self, graph: &Graph, samples: &[f64], targets: &[f64], first: usize, loss: LossFunction, config: Config) -> Result<(Vec<f64>, EpochMetrics)> {
		let input = graph.input.elements();
		let output = graph.output.elements();
		require(input != 0 && samples.len() % input == 0, format!("evaluation samples must be a multiple of {input} values"))?;
		let rows = samples.len() / input;
		require(targets.len() == rows * output, format!("evaluation targets must hold {rows} rows of {output} values"))?;
		require(first <= rows, format!("evaluation start row {first} exceeds {rows} rows"))?;
		let saved_rows = self.rows;
		let result = (|| {
			self.upload_weights(&graph.parameters)?;
			let evaluation_count = checked_mul(self.capacity, input, "native evaluation sample allocation")?;
			let target_count = checked_mul(self.capacity, output, "native evaluation target allocation")?;
			let evaluation_samples = Buffer::upload_float(self.program.gpu, &vec![0.0; evaluation_count], self.program.artifact.layout.input_precision)?;
			let evaluation_targets = Buffer::upload_float(self.program.gpu, &vec![0.0; target_count], self.program.artifact.layout.output_precision)?;
			let mut predictions = Vec::new();
			let mut measured = Vec::new();
			let mut row = first;
			while row < rows {
				let end = row.checked_add(self.capacity).map_or(rows, |end| end.min(rows));
				self.rows = narrow(end - row, "native evaluation rows")? as u32;
				evaluation_samples.write_float_bytes(0, &samples[row * input..end * input], self.program.artifact.layout.input_precision)?;
				evaluation_targets.write_float_bytes(0, &targets[row * output..end * output], self.program.artifact.layout.output_precision)?;
				self.values.clear()?;
				for &(start, stop) in &self.context_resets {
					self.contexts.clear_range(start, stop - start)?;
				}
				measured.push(self.metric_launch_with(evaluation_samples.pointer, evaluation_targets.pointer, config)?);
				predictions.extend(self.predictions()?);
				row = end;
			}
			let count = measured.iter().map(|part| part.count).sum::<usize>().max(1);
			let seconds = measured.iter().map(|part| part.device_seconds).sum();
			let mut metrics = EpochMetrics::combine(measured.into_iter().map(|part| { let share = part.count as f64 / count as f64; (part, share) }), loss.0 == 1);
			metrics.device_seconds = seconds;
			Ok((predictions, metrics))
		})();
		self.rows = saved_rows;
		result
	}
	/// The runs of the one-row input that the input positions `begin..end`
	/// occupy: one run of ids for a graph that starts with a gather, and one run
	/// per channel otherwise, as the arenas hold a row channel by channel.
	fn input_runs(&self, begin: u32, end: u32) -> Vec<(usize, usize)> {
		if self.vocabulary > 0.0 { vec![(begin as usize, (end - begin) as usize)] } else { window_runs(self.input, begin, end) }
	}
	/// Replace a run of the input values from element `first`. A graph that
	/// starts with a gather holds its input as i32 token ids.
	fn write_samples(&self, first: usize, values: &[f64]) -> Result<()> {
		let request = self.request.lock().map_err(|_| RecipeError::new("request buffers are poisoned"))?;
		let (buffer, first) = if self.program.artifact.layout.request_control.is_some() {
			let request = request.as_ref().ok_or_else(|| RecipeError::new("request input was not prepared"))?;
			let position = first % self.input.length;
			let packed = first == request.begin as usize && values.len() == checked_mul(self.input.channels, request.positions, "request input count")?;
			require(packed || request.positions == self.input.length || position >= request.begin as usize && position + values.len() <= request.begin as usize + request.positions, "input write is outside the request window")?;
			let offset = if packed { 0 } else { (first / self.input.length) * request.positions + position - request.begin as usize };
			(&request.input, offset)
		} else { (&self.samples, first) };
		if self.vocabulary > 0.0 {
			let ids = values.iter().map(|value| token_id(*value, self.vocabulary).map(i32::to_ne_bytes)).collect::<Result<Vec<_>>>()?;
			buffer.write_bytes(checked_mul(first, size_of::<i32>(), "token offset")?, ids.as_flattened())
		} else {
			let input_precision = self.program.artifact.layout.input_precision;
			buffer.write_float_bytes(checked_mul(first, input_precision.bytes(), "sample offset")?, values, input_precision)
		}
	}
	fn write_tokens(&self, first: usize, values: &[f64]) -> Result<()> {
		let mut tokens = self.tokens.lock().map_err(|_| RecipeError::new("token state is poisoned"))?;
		let end = checked_add(first, values.len(), "token write")?;
		let target = tokens.get_mut(first..end).ok_or_else(|| RecipeError::new("token write exceeds the sequence"))?;
		target.copy_from_slice(values);
		Ok(())
	}
	/// The output positions the input positions `begin..end` reach: the window
	/// every node derives from its source, as the emitted forward derives it,
	/// carried to the last node.
	fn output_window(&self, begin: u32, end: u32) -> Result<(u32, u32)> {
		let mut windows = Vec::with_capacity(self.nodes.len());
		for node in &self.nodes {
			let (begin, end) = usize::try_from(node.source).map_or((begin, end), |source| windows[source]);
			let length = narrow(node.output.length, "node length")? as u32;
			windows.push(match node.op {
				Primitive::Predictor => (0, length),
				Primitive::Pool => {
					let size = integer_argument(node.argument[0], "pool size")? as u32;
					require(size > 0, "native pool size must be positive")?;
					(begin / size, end.div_ceil(size).min(length))
				}
				Primitive::Last => (0, 1),
				Primitive::Contraction if node.argument[0] > 1.0 => {
					let lag = integer_argument(node.argument[0], "contraction kernel")? as u32 - 1;
					(begin.saturating_sub(lag), end.saturating_sub(lag))
				}
				_ => (begin, end),
			});
		}
		windows.last().copied().ok_or_else(|| RecipeError::new("native model has no node"))
	}
	/// Restore the token, input, and mutable arenas before a new sequence, while
	/// retaining packed tables and saved evaluation statistics.
	fn reset_sequence(&self) -> Result<()> {
		self.tokens.lock().map_err(|_| RecipeError::new("token state is poisoned"))?.fill(0.0);
		self.samples.clear()?;
		self.values.clear()?;
		self.context_resets.iter().try_for_each(|&(start, end)| self.contexts.clear_range(start, end - start))
	}
	/// The bytes this tape holds on its device: the weights, the input row, and
	/// the value and context arenas that keep every position's activations,
	/// attention keys and values, recurrent state, convolution tail and batch
	/// normalization statistics.
	fn resident_bytes(&self) -> usize {
		let (input, output) = self.request_bytes();
		self.weights.bytes + self.samples.bytes + self.values.bytes + self.contexts.bytes + input + output
	}
	fn request_bytes(&self) -> (usize, usize) {
		self.request.lock().unwrap().as_ref().map_or((0, 0), |request| (request.input.bytes, request.output.bytes + request.hidden.bytes + request.lookups.iter().map(|buffer| buffer.bytes).sum::<usize>()))
	}
	/// `RECIPE_ALL_LOGITS=<path>` appends every output position this window kept:
	/// a u32 position, then the vocabulary's logits as f32, all little-endian.
	/// Positions whose rows the request layout no longer holds are skipped.
	/// The file writes run on their own thread; `flush_logits` waits for them and returns their first error.
	fn record_logits(&self, predictions: &[f64], begin: u32, end: u32) -> Result<()> {
		let Some(writer) = logits_writer() else { return Ok(()) };
		let (first, reached) = self.output_window(begin, end)?;
		let mut bytes = Vec::with_capacity((reached.saturating_sub(first) as usize) * (4 + 4 * self.output.channels));
		for position in first..reached {
			let Ok(logits) = self.logits_at(predictions, position as usize) else { continue };
			bytes.extend_from_slice(&position.to_le_bytes());
			bytes.extend(logits.iter().flat_map(|value| (*value as f32).to_le_bytes()));
		}
		writer.send(LogitsMessage::Bytes(bytes)).map_err(|_| RecipeError::new("the logits writer has stopped"))
	}
	/// The logits of the last reached position, using the current request's output layout.
	fn last_logits(&self, predictions: &[f64], begin: u32, end: u32) -> Result<Vec<f64>> {
		let (_, reached) = self.output_window(begin, end)?;
		require(reached != 0, "decode window reaches no output position")?;
		self.logits_at(predictions, reached as usize - 1)
	}
	fn logits_at(&self, predictions: &[f64], position: usize) -> Result<Vec<f64>> {
		if predictions.len() == self.output.elements() { return select_last_logits(predictions, self.output, position); }
		let request = self.request.lock().map_err(|_| RecipeError::new("request buffers are poisoned"))?;
		if let Some(request) = request.as_ref() {
			let (length, position) = if self.output.length == 1 { (1, 0) } else {
				(request.positions, position.checked_sub(request.begin as usize).ok_or_else(|| RecipeError::new("logits precede the request window"))?)
			};
			select_last_logits(predictions, Shape { channels: self.output.channels, length }, position)
		} else { select_last_logits(predictions, self.output, position) }
	}
	fn inject_bn_stats(&self, stats: &[f64]) -> Result<()> {
		let expected = self.batch_normalizations.iter().map(|(_, values)| values).sum::<usize>();
		require(stats.len() == expected, format!("batch normalization expected {expected} saved statistics, received {}", stats.len()))?;
		let mut offset = 0;
		for &(node, values) in &self.batch_normalizations {
			let end = offset + values;
			self.contexts.write_float_bytes(self.program.artifact.layout.contexts[node], &stats[offset..end], self.program.artifact.layout.precisions[node])?;
			offset = end;
		}
		Ok(())
	}
	fn extract_bn_stats(&self) -> Result<Vec<f64>> {
		let mut stats = Vec::new();
		for &(node, values) in &self.batch_normalizations {
			stats.extend(self.contexts.download_float_bytes(self.program.artifact.layout.contexts[node], values, self.program.artifact.layout.precisions[node])?);
		}
		Ok(stats)
	}
	fn predictions(&self) -> Result<Vec<f64>> {
		let request = self.request.lock().map_err(|_| RecipeError::new("request buffers are poisoned"))?;
		if let Some(request) = request.as_ref() {
			let positions = if self.output.length == 1 { 1 } else { request.positions };
			let values = request.output.download_float_bytes(0, self.output.channels * positions, self.program.artifact.layout.output_precision)?;
			self.trace_output_values(&values)?;
			return Ok(values);
		}
		drop(request);
		self.output(0, self.rows as usize * self.output.elements())
	}
	fn saved_predictions(&self, predictions: Vec<f64>) -> Result<Vec<f64>> {
		let request = self.request.lock().map_err(|_| RecipeError::new("request buffers are poisoned"))?;
		let Some(request) = request.as_ref().filter(|_| self.output.length > 1) else { return Ok(predictions) };
		let mut saved = self.saved_output.lock().map_err(|_| RecipeError::new("saved outputs are poisoned"))?;
		saved.resize(self.output.elements(), 0.0);
		if request.begin == 0 { saved.fill(0.0); }
		for channel in 0..self.output.channels {
			let source = channel * request.positions;
			let target = channel * self.output.length + request.begin as usize;
			saved[target..target + request.positions].copy_from_slice(&predictions[source..source + request.positions]);
		}
		Ok(saved.clone())
	}
	fn trace_output_values(&self, values: &[f64]) -> Result<()> {
		// A traced run shows the head of every node's values once, at the first
		// output, and again if a later output went nonfinite.
		static SHOWN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
		if tracing() && (!SHOWN.swap(true, std::sync::atomic::Ordering::Relaxed) || !values.iter().all(|value| value.is_finite())) {
			let layout = &self.program.artifact.layout;
			let reached = self.reached.load(Ordering::Relaxed) as usize;
			// The first two blocks and the model's last nodes: enough to place a
			// divergence, without reading every arena of a deep model.
			// RECIPE_TRACE_NODES=a..b names another range of nodes instead.
			let total = layout.values.len();
			// RECIPE_TRACE_DUMP=a..b also prints nodes whose slots stay reusable: what
			// a slot holds after the forward, not what the node wrote.
			let extra = std::env::var("RECIPE_TRACE_DUMP").ok().and_then(|text| { let (from, to) = text.split_once("..")?; Some((from.trim().parse::<usize>().ok()?, to.trim().parse::<usize>().ok()?)) });
			for (index, (slot, precision)) in layout.values.iter().zip(&layout.precisions).enumerate().filter(|(index, _)| traced_node(*index, total) || extra.is_some_and(|(from, to)| (from..to).contains(index))) {
				let shape = window_shape(self.nodes[index].output, self.input.length, layout.window_positions);
				let (channels, length) = (shape.channels, shape.length);
				let positions = if layout.window_positions < self.input.length { reached.saturating_sub(self.window_begin.load(Ordering::Relaxed) as usize) } else { reached }.clamp(1, length.max(1));
				// The arena is channel-major over the whole context, so the bytes up
				// to the last reached position of the last channel come back raw and
				// only the reached positions are unpacked.
				let bytes = precision.bytes();
				let needed = checked_mul(channels.saturating_sub(1) * length + positions, bytes, "traced node bytes")?;
				// A wide arena over a long context is read whole only up to 64 MB;
				// past that the head and the tail come back on their own and the sum
				// is left out, so a traced deep model still answers inside a cap.
				let whole = needed <= 64 << 20;
				let region = if whole { self.values.download_range::<u8>(*slot, needed)? } else { Vec::new() };
				let one = |channel: usize, position: usize| -> Result<f64> {
					let start = (channel * length + position) * bytes;
					let chunk = if whole { region.get(start..start + bytes).map(<[u8]>::to_vec) } else { Some(self.values.download_range::<u8>(*slot + start, bytes)?) };
					Ok(chunk.map_or(f64::NAN, |chunk| {
						let mut bits = [0_u8; 8];
						bits[..bytes].copy_from_slice(&chunk);
						precision.unpack(u64::from_le_bytes(bits))
					}))
				};
				let first = (0..3.min(channels)).map(|channel| one(channel, 0)).collect::<Result<Vec<_>>>()?;
				let last = (channels.saturating_sub(3)..channels).map(|channel| one(channel, positions - 1)).collect::<Result<Vec<_>>>()?;
				// RECIPE_TRACE_CHANNELS=4096,5120 also prints three values from each
				// named channel at the first and the last position: a joined
				// projection's later heads against a reference that dumps them apart.
				let mut at = String::new();
				for start in std::env::var("RECIPE_TRACE_CHANNELS").ok().into_iter().flat_map(|list| list.split(',').filter_map(|text| text.trim().parse::<usize>().ok()).collect::<Vec<_>>()) {
					if start < channels {
						let values = (start..(start + 3).min(channels)).map(|channel| one(channel, 0)).collect::<Result<Vec<_>>>()?;
						let ending = (start..(start + 3).min(channels)).map(|channel| one(channel, positions - 1)).collect::<Result<Vec<_>>>()?;
						at.push_str(&format!(" at {start} {values:?} ending {ending:?}"));
						// RECIPE_TRACE_ROW=p prints every channel at position p, once per node;
						// RECIPE_TRACE_ROW=all prints every reached position.
						if start == 0 {
							if let Ok(text) = std::env::var("RECIPE_TRACE_ROW") {
								let rows = if text == "all" { (0..positions).collect::<Vec<_>>() } else { text.parse::<usize>().ok().filter(|position| *position < positions).into_iter().collect() };
								for position in rows {
									let row = (0..channels).map(|channel| one(channel, position)).collect::<Result<Vec<_>>>()?;
									at.push_str(&format!(" row {position} {row:?}"));
								}
							}
						}
						// RECIPE_TRACE_POSITIONS=1 also prints the three values at every position.
						if std::env::var("RECIPE_TRACE_POSITIONS").is_ok() {
							let rows = (0..positions).map(|position| (start..(start + 3).min(channels)).map(|channel| one(channel, position)).collect::<Result<Vec<_>>>()).collect::<Result<Vec<_>>>()?;
							at.push_str(&format!(" positions {rows:?}"));
						}
					}
				}
				let sum = if whole {
					(0..channels).flat_map(|channel| (0..positions).map(move |position| (channel, position))).map(|(channel, position)| one(channel, position)).sum::<Result<f64>>()?.to_string()
				} else {
					"-".to_owned()
				};
				trace(&format!("values node {index} {} {channels}x{positions} first {first:?} last {last:?}{at} sum {sum}", self.nodes[index].identity(index)))?;
			}
		}
		Ok(())
	}
	/// Read `count` output values starting at `first`.
	fn output(&self, first: usize, count: usize) -> Result<Vec<f64>> {
		let request = self.request.lock().map_err(|_| RecipeError::new("request buffers are poisoned"))?;
		if let Some(request) = request.as_ref() {
			let (length, begin) = if self.output.length == 1 { (1, 0) } else { (request.positions, request.begin as usize) };
			let position = first % self.output.length;
			require(length == self.output.length || position >= begin && position + count <= begin + length, "output read is outside the request window")?;
			let offset = (first / self.output.length) * length + position - begin;
			let precision = self.program.artifact.layout.output_precision;
			let values = request.output.download_float_bytes(checked_mul(offset, precision.bytes(), "request output offset")?, count, precision)?;
			self.trace_output_values(&values)?;
			return Ok(values);
		}
		drop(request);
		let arena = *self.program.artifact.layout.values.last().ok_or_else(|| RecipeError::new("native model has no output arena"))?;
		let output_precision = self.program.artifact.layout.output_precision;
		let offset = checked_add(arena, checked_mul(first, output_precision.bytes(), "output offset")?, "output arena offset")?;
		let values = self.values.download_float_bytes(offset, count, output_precision)?;
		self.trace_output_values(&values)?;
		require(values.iter().all(|value| value.is_finite()), format!("device {} produced a nonfinite prediction", self.program.gpu.name)).map(|_| values)
	}
	fn capture_tensors(&self, begin: u32, end: u32) -> Result<Vec<TensorObservation>> {
		if self.observations == 0 { return Ok(Vec::new()); }
		require(begin <= end && end <= self.positions, "tensor observation window is outside the tape")?;
		self.program.gpu.synchronize()?;
		let mut tensors = Vec::new();
		for (index, node) in self.nodes.iter().enumerate() {
			let Some(site) = node.observation.filter(|site| self.observations & site.family != 0) else { continue };
			let shape = window_shape(node.output, self.input.length, self.program.artifact.layout.window_positions);
			let precision = self.program.artifact.layout.precisions[index];
			let count = graph_rows_buffer(shape, self.rows as usize, precision.bytes())?;
			let bytes = self.values.download_completed_bytes(self.program.artifact.layout.values[index], count)?;
			tensors.push(TensorObservation {
				name: site.name, device: self.device_label()?, block: node.block_index, node: index, row_start: 0,
				shape: [self.rows as usize, shape.channels, shape.length], input_window: [begin, end], dtype: precision.label(), bytes,
			});
		}
		Ok(tensors)
	}
	fn take_tensors(&self) -> Result<Vec<TensorObservation>> {
		Ok(std::mem::take(&mut *self.tensor_history.lock().map_err(|_| RecipeError::new("tensor observation history is poisoned"))?))
	}
	fn predictions_at(&self, node: i32, output: usize) -> Result<Vec<f64>> {
		let index = usize::try_from(node).map_err(|_| RecipeError::new("native output source is absent"))?;
		let offset = *self.program.artifact.layout.values.get(index).ok_or_else(|| RecipeError::new("native model output arena is absent"))?;
		let values = self.values.download_float_bytes(offset, self.rows as usize * output, self.program.artifact.layout.precisions[index])?;
		require(values.iter().all(|value| value.is_finite()), format!("device {} produced a nonfinite prediction", self.program.gpu.name)).map(|_| values)
	}
	fn epoch_launch(&mut self, rate: f64, config: Config, operation: EpochOperation) -> Result<()> {
		self.epoch_launch_with(rate, config, operation, self.samples.pointer, self.targets.pointer)
	}
	fn epoch_launch_with(&mut self, rate: f64, config: Config, operation: EpochOperation, samples: u64, targets: u64) -> Result<()> {
		require(self.step != 0 || matches!(operation, EpochOperation::Metrics), "optimizer epoch is absent")?;
		let threads = self.program.dispatch(NativeEntry::Epoch)?.geometry.threads()?;
		let rows = self.rows;
		let thread_count = threads;
		let beta1 = self.precision.state.below_one(config.beta1);
		let beta2 = self.precision.state.below_one(config.beta2);
		let epsilon = self.precision.state.optimizer_epsilon(config.epsilon);
		let beta1_power = beta1.powi(self.step as i32);
		let beta2_power = beta2.powi(self.step as i32);
		let decay = config.decay;
		let encoded = [rate, beta1, beta2, beta1_power, beta2_power, epsilon, decay].map(|value| self.precision.state.pack(value));
		let run_gradient = u32::from(operation.gradient());
		let run_optimizer = u32::from(operation.optimizer());
		let mut call = ptrs![
			samples,
			targets,
			self.weights.pointer,
			self.frozen.pointer,
			self.moments.pointer,
			self.variances.pointer,
			self.gradient.pointer,
			self.metrics.pointer,
			self.input_adjoint.pointer,
			self.values.pointer,
			self.contexts.pointer,
			self.adjoints.pointer,
			rows,
			thread_count,
			encoded[0],
			encoded[1],
			encoded[2],
			encoded[3],
			encoded[4],
			encoded[5],
			encoded[6],
			run_gradient,
			run_optimizer
		];
		trace(&format!("epoch {} {operation:?} launch", self.step))?;
		let machine_started = Instant::now();
		self.program.launch_epoch(&mut call).map_err(|error| RecipeError::new(format!("training epoch: {error}")))?;
		trace(&format!("epoch {} {operation:?} submitted", self.step))?;
		self.program.gpu.synchronize()?;
		let ticks = self.contexts.download_range::<i64>(self.program.artifact.layout.timing / 8, 2)?;
		let seconds = if self.program.gpu.backend == Backend::Cpu { machine_started.elapsed().as_secs_f64() } else { ticks[1].wrapping_sub(ticks[0]).max(0) as f64 / 1e9 };
		self.last_device_seconds.store(seconds.to_bits(), Ordering::Release);
		trace(&format!("epoch {} {operation:?} launch complete", self.step))?;
		Ok(())
	}
	fn epoch_metrics(&self) -> Result<EpochMetrics> {
		let values = self.metrics.download_float(EpochMetrics::VALUES, self.program.artifact.layout.output_adjoint_precision)?;
		trace(&format!("epoch {} metric complete", self.step))?;
		Ok(EpochMetrics::read(&values, self.rows as usize * self.output.elements(), f64::from_bits(self.last_device_seconds.load(Ordering::Acquire))))
	}
	fn metric_launch(&mut self, config: Config) -> Result<EpochMetrics> {
		self.epoch_launch(0.0, config, EpochOperation::Metrics)?;
		self.epoch_metrics()
	}
	fn metric_launch_with(&mut self, samples: u64, targets: u64, config: Config) -> Result<EpochMetrics> {
		self.epoch_launch_with(0.0, config, EpochOperation::Metrics, samples, targets)?;
		self.epoch_metrics()
	}
	fn objective(&self) -> Result<f64> {
		Ok(self.epoch_metrics()?.loss)
	}
	fn full_epoch(&mut self, rate: f64, config: Config) -> Result<f64> {
		self.epoch_launch(rate, config, EpochOperation::Full)?;
		let objective = self.objective()?;
		Ok(objective)
	}
	/// Computes this shard's loss and reduced parameter gradient without
	/// changing optimizer state or model weights.
	fn gradient_launch(&mut self, rate: f64, config: Config) -> Result<f64> {
		self.epoch_launch(rate, config, EpochOperation::Gradient)?;
		self.objective()
	}
	/// Applies the emitted AdamW operation to the gradient already stored on
	/// this tape's device through the same model epoch entrypoint.
	fn optimizer_launch(&mut self, rate: f64, config: Config) -> Result<()> {
		self.epoch_launch(rate, config, EpochOperation::Optimizer)
	}
	fn advance(&mut self) -> Result<()> {
		self.step = self.step.checked_add(1).ok_or_else(|| RecipeError::new("optimizer epoch overflows"))?;
		Ok(())
	}
	/// Each parameterized node's span: arena byte offset, count, arithmetic.
	fn weight_segments(&self) -> Vec<(usize, usize, Compute)> {
		let layout = &self.program.artifact.layout;
		layout.weights.iter().zip(&layout.spans).zip(&layout.precisions).filter(|((_, (_, count)), _)| *count != 0).map(|((offset, (_, count)), precision)| (*offset, *count, *precision)).collect()
	}
	fn weights(&self) -> Result<Vec<f64>> {
		let mut values = Vec::with_capacity(self.parameters);
		for (offset, count, precision) in self.weight_segments() {
			values.extend(self.weights.download_float_bytes(offset, count, precision)?);
		}
		Ok(values)
	}
	fn gradient_segments(&self) -> Vec<(usize, usize, Compute)> {
		let layout = &self.program.artifact.layout;
		layout.gradients.iter().zip(&layout.spans).zip(&layout.gradient_precisions).filter(|((_, (_, count)), _)| *count != 0).map(|((offset, (_, count)), precision)| (*offset, *count, *precision)).collect()
	}
	/// The reduced full-shard parameter gradient the last epoch dispatch left
	/// on the device.
	fn download_gradient(&self) -> Result<Vec<f64>> {
		let mut values = Vec::with_capacity(self.parameters);
		for (offset, count, precision) in self.gradient_segments() {
			values.extend(self.gradient.download_float_bytes(offset, count, precision)?);
		}
		Ok(values)
	}
	fn upload_gradient(&self, gradient: &[f64]) -> Result<()> {
		let mut at = 0;
		for (offset, count, precision) in self.gradient_segments() {
			let span = gradient.get(at..at + count).ok_or_else(|| RecipeError::new("gradient upload is shorter than the parameters"))?;
			self.gradient.write_float_bytes(offset, span, precision)?;
			at += count;
		}
		Ok(())
	}
	fn upload_weights(&self, weights: &[f64]) -> Result<()> {
		let mut at = 0;
		for (offset, count, precision) in self.weight_segments() {
			let span = weights.get(at..at + count).ok_or_else(|| RecipeError::new("weight upload is shorter than the parameters"))?;
			self.weights.write_float_bytes(offset, span, precision)?;
			at += count;
		}
		Ok(())
	}
	/// The axes of the model's sectioned rotary blocks, which all share one count.
	fn rope_axes(&self) -> Result<usize> {
		let mut axes = None;
		for node in &self.nodes {
			if let Some(layout) = rope_sections(node, &self.programs)? {
				require(axes.is_none_or(|axes| axes == layout.axes()), "the sectioned rotary blocks disagree on their axes")?;
				axes = Some(layout.axes());
			}
		}
		axes.ok_or_else(|| RecipeError::new("the model has no sectioned rotary block to take positions"))
	}
	/// The position of every token on every rotary axis, `[row][position][axis]`
	/// over this tape's rows and the sequence, written to every sectioned rotary
	/// node. A tape without one is an error, since the positions would be lost.
	fn set_rope_positions(&self, positions: &[u32]) -> Result<()> {
		let mut written = false;
		for (index, node) in self.nodes.iter().enumerate() {
			if let Some(layout) = rope_sections(node, &self.programs)? {
				let region = rope_context_region(layout, self.rows as usize, node.output.length, Some(positions))?;
				self.contexts.write_bytes(self.program.artifact.layout.contexts[index], &region)?;
				written = true;
			}
		}
		require(written, "the model has no sectioned rotary block to take positions")
	}
	fn optimizer_state(&self) -> Result<(Vec<f64>, Vec<f64>, Vec<f64>)> {
		Ok((self.weights()?, self.moments.download_float(self.parameters, self.precision.state)?, self.variances.download_float(self.parameters, self.precision.state)?))
	}
	fn capture(&self, graph: &mut Graph) -> Result<()> {
		let (weights, moments, variances) = self.optimizer_state()?;
		graph.parameters = weights;
		graph.state.moments = moments;
		graph.state.variances = variances;
		graph.state.epoch = self.step as usize;
		graph.state.best_loss = self.best_loss.to_vec();
		Ok(())
	}
	fn tile(&self) -> Tile {
		self.program.tile
	}
	/// The dispatched contraction schedule, in model execution order: one
	/// forward/gradient/previous group per contraction node, collapsed to a single
	/// extent only when every group agrees.
	fn schedule(&self) -> String {
		let extents = self
			.program
			.schedule
			.contractions
			.iter()
			.flatten()
			.flat_map(|node| [node.forward, node.gradient, node.previous])
			.map(|extent| format!("{}x{}x{}", extent.m, extent.n, extent.k))
			.collect::<Vec<_>>();
		if extents.windows(2).all(|pair| pair[0] == pair[1]) {
			return extents.first().cloned().unwrap_or_default();
		}
		self.program
			.schedule
			.contractions
			.iter()
			.flatten()
			.map(|node| [node.forward, node.gradient, node.previous].map(|extent| format!("{}x{}x{}", extent.m, extent.n, extent.k)).join("/"))
			.collect::<Vec<_>>()
			.join(" ")
	}
	fn device_label(&self) -> Result<String> {
		device_label(self.program.gpu)
	}
}
fn device_label(gpu: &Gpu) -> Result<String> {
	if gpu.name.contains(':') { Ok(gpu.name.clone()) } else { Ok(format!("{}:{}", local_host()?, gpu.name)) }
}
/// Tracks the running best loss and decides whether this epoch triggers a
/// checkpoint, updating the four-slot loss state in place.
fn observe_loss(best_loss: &mut [f64; 4], loss: f64, tolerance: f64) -> bool {
	let (old_best, last, armed, saved) = (best_loss[0], best_loss[1], best_loss[2].is_finite(), best_loss[3]);
	let best = if loss < old_best { loss } else { old_best };
	let trigger = armed && loss > last * (2.0 - tolerance) && tolerance > 0.0;
	best_loss[0] = best;
	best_loss[1] = loss;
	best_loss[2] = if trigger {
		f64::NAN
	} else if last.is_finite() && last < saved && loss < saved {
		best
	} else {
		best_loss[2]
	};
	if trigger {
		best_loss[3] = best;
	}
	trigger
}
/// One measured direction of a topology link.
#[derive(Clone, Copy)]
struct TransferCost {
	latency: Duration,
	bandwidth: f64,
}
/// The measured behavior of one device: the two transfer directions between it and the coordinating
/// machine, the gradient work it retires each second, and the fixed cost of one dispatch on it.
#[derive(Clone, Copy)]
struct Link {
	to_host: TransferCost,
	from_host: TransferCost,
	work: f64,
	overhead: f64,
}
fn measure_link(gpu: &'static Gpu, config: Config) -> Result<Link> {
	let probe_bytes = parse_natural(env!("RECIPE_TOPOLOGY_PROBE_BYTES"), "topology probe bytes must be a positive integer");
	let mut scratch = vec![0_u8; probe_bytes];
	let pointer = gpu.upload(0, scratch.as_ptr().cast(), probe_bytes)?;
	let measured = (|| {
		gpu.synchronize()?;
		let started = Instant::now();
		gpu.download(scratch.as_mut_ptr().cast(), pointer, 1)?;
		gpu.synchronize()?;
		let to_host_latency = started.elapsed();
		let started = Instant::now();
		gpu.download(scratch.as_mut_ptr().cast(), pointer, probe_bytes)?;
		gpu.synchronize()?;
		let to_host_bandwidth = probe_bytes as f64 / started.elapsed().as_secs_f64().max(f64::EPSILON);
		let started = Instant::now();
		gpu.upload(pointer, scratch.as_ptr().cast(), 1)?;
		gpu.synchronize()?;
		let from_host_latency = started.elapsed();
		let started = Instant::now();
		gpu.upload(pointer, scratch.as_ptr().cast(), probe_bytes)?;
		gpu.synchronize()?;
		let from_host_bandwidth = probe_bytes as f64 / started.elapsed().as_secs_f64().max(f64::EPSILON);
		let (work, overhead) = calibrate(gpu, config)?;
		Ok(Link {
			to_host: TransferCost { latency: to_host_latency, bandwidth: to_host_bandwidth },
			from_host: TransferCost { latency: from_host_latency, bandwidth: from_host_bandwidth },
			work,
			overhead,
		})
	})();
	gpu.free(pointer);
	measured
}
static LINKS: OnceLock<Result<Vec<Link>>> = OnceLock::new();
#[derive(Clone, Copy)]
struct Transfer {
	from: usize,
	to: usize,
	bytes: usize,
	cost: TransferCost,
}
/// The route one training run takes: the row share of every shard, the movement its fused epoch performs, and the
/// complete epoch predicted for it from computation, transfers, synchronization, and persistent-state movement.
struct Placement {
	shares: Vec<f64>,
	gradient_to_host: Vec<Transfer>,
	gradient_to_primary: Transfer,
	weights_to_host: Transfer,
	weights_from_host: Vec<Transfer>,
	loss: LossFunction,
	predicted: [f64; 4],
}
impl Placement {
	fn movements(&self) -> impl Iterator<Item = &Transfer> {
		self.gradient_to_host.iter().chain([&self.gradient_to_primary, &self.weights_to_host]).chain(&self.weights_from_host)
	}
	fn seconds(&self) -> f64 {
		self.predicted.iter().sum()
	}
}
/// The planned gradient work of one fused epoch over `rows` rows: every
/// contraction's forward, gradient, and previous-adjoint tile, every node's
/// elementwise traffic, and the loss reduction. The one optimizer update the
/// leading device applies is priced once, separately, by `optimizer_work`.
fn gradient_work(graph: &Graph, rows: usize) -> Result<f64> {
	let tiles = native_contraction_shapes(graph, rows)?
		.iter()
		.flatten()
		.flat_map(|shapes| [shapes.forward, shapes.gradient, shapes.previous])
		.map(|extent| 2.0 * f64::from(extent.m) * f64::from(extent.n) * f64::from(extent.k))
		.sum::<f64>();
	let elementwise = graph.nodes.iter().map(|node| 8.0 * rows as f64 * node.output.elements() as f64).sum::<f64>();
	Ok(8.0 * checked_mul(rows, graph.output.elements(), "predicted loss reduction")? as f64 + tiles + elementwise)
}
fn optimizer_work(graph: &Graph) -> f64 {
	16.0 * graph.parameters.len() as f64
}
/// Measures one device through the configured surrogate workload. The optimizer
/// dispatch isolates fixed cost, and the gradient dispatch measures planned work
/// without allocating, forwarding, training, or dispatching the placed model.
fn calibrate(gpu: &'static Gpu, config: Config) -> Result<(f64, f64)> {
	let workers = match &gpu.driver {
		Driver::Cpu if gpu.backend == Backend::Cpu => cpu_worker_threads()?,
		Driver::Remote(remote) if gpu.backend == Backend::Cpu => remote.worker_threads,
		_ => 1,
	};
	let workers = usize::try_from(workers).map_err(|_| RecipeError::new("CPU worker count exceeds usize"))?;
	require(workers != 0, "CPU worker count is empty")?;
	let rows = checked_mul(checked_mul(config.surrogate_epochs, config.surrogate_width, "surrogate rows")?, workers, "parallel surrogate rows")?;
	let features = config.surrogate_width;
	let samples = (0..rows * features).map(|value| ((value % 17) as f64 - 8.0) / 8.0).collect::<Vec<_>>();
	let targets = (0..rows).map(|value| ((value % 5) as f64 - 2.0) / 2.0).collect::<Vec<_>>();
	let prepared = Prepared {
		samples: samples.clone(),
		targets: targets.clone(),
		target_width: 1,
		rows,
		source_rows: rows,
		features,
		schema: DataSchema::default(),
		sequence: None,
		target_categorical: false,
		norm_mean: Vec::new(),
		norm_scale: Vec::new(),
		identities: Vec::new(),
		fitted: Vec::new(),
		bound: None,
	};
	let graph = compile(&surrogate_model(config.surrogate_width, config.precision, config.precision), &prepared, &targets, rows, gpu, config, true)?;
	let mut tape = NativeTape::new(&graph, TapeInput::Values(&samples), &samples, &targets, gpu, config.precision, Some(mse))?;
	let timed = |tape: &mut NativeTape, gradient: bool| -> Result<f64> {
		tape.advance()?;
		let started = Instant::now();
		if gradient {
			tape.full_epoch(config.surrogate_rate, config)?;
		} else {
			tape.optimizer_launch(config.surrogate_rate, config)?;
		}
		gpu.synchronize()?;
		Ok(started.elapsed().as_secs_f64())
	};
	// Warm up both paths, then use minimum timings to reduce scheduling noise.
	timed(&mut tape, true)?;
	timed(&mut tape, false)?;
	let (mut overhead, mut epoch) = (f64::INFINITY, f64::INFINITY);
	for _ in 0..config.surrogate_epochs {
		overhead = overhead.min(timed(&mut tape, false)?);
		epoch = epoch.min(timed(&mut tape, true)?);
	}
	let gradient = epoch - overhead;
	require(gradient.is_finite() && gradient > 0.0, "surrogate gradient time must be finite and positive")?;
	Ok(((gradient_work(&graph, rows)? / gradient).max(1.0), overhead))
}
/// Computes a positive row share for every device without allowing a malformed
/// or non-finite work value to underflow the remaining-row calculation.
fn route_counts(route: &[usize], links: &[Link], rows: usize, policy: MultiDevice) -> Result<Vec<usize>> {
	require(!route.is_empty() && route.len() <= rows, "route row capacity is invalid")?;
	let total = route.iter().map(|device| if policy == MultiDevice::Auto { 1.0 } else { links[*device].work }).sum::<f64>();
	require(total.is_finite() && total > 0.0, "route work is invalid")?;
	let remaining = rows - route.len();
	let mut counts = vec![1_usize; route.len()];
	let mut remainders = Vec::with_capacity(route.len());
	for (index, device) in route.iter().enumerate() {
		let work = if policy == MultiDevice::Auto { 1.0 } else { links[*device].work };
		let exact = remaining as f64 * work / total;
		require(exact.is_finite() && (0.0..=remaining as f64).contains(&exact), "route share is invalid")?;
		let base = exact.floor() as usize;
		counts[index] += base;
		remainders.push((exact - base as f64, index));
	}
	let assigned = counts.iter().sum::<usize>();
	let left = rows.checked_sub(assigned).ok_or_else(|| RecipeError::new("route shares exceed the available rows"))?;
	remainders.sort_by(|left, right| right.0.total_cmp(&left.0).then(left.1.cmp(&right.1)));
	require(left <= remainders.len(), "route shares leave too many rows")?;
	for &(_, index) in remainders.iter().take(left) {
		counts[index] += 1;
	}
	Ok(counts)
}
/// Plans one candidate route from the workload and storage plan already established for this run: the row share of
/// every shard, the movement list its fused epoch performs, and the complete epoch that movement and each device's
/// measured behavior predict.
fn plan_route(route: &[usize], links: &[Link], graph: &Graph, rows: usize, bytes: (usize, usize), loss: LossFunction, policy: MultiDevice) -> Result<(Vec<usize>, Placement)> {
	let counts = route_counts(route, links, rows, policy)?;
	let (gradient_bytes, weight_bytes) = bytes;
	let (gradient_to_host, weights_from_host) = (
		route.iter().enumerate().map(|(shard, device)| Transfer { from: shard + 1, to: 0, bytes: gradient_bytes, cost: links[*device].to_host }).collect::<Vec<_>>(),
		route.iter().enumerate().skip(1).map(|(shard, device)| Transfer { from: 0, to: shard + 1, bytes: weight_bytes, cost: links[*device].from_host }).collect::<Vec<_>>(),
	);
	let placement = Placement {
		shares: counts.iter().map(|count| *count as f64 / rows as f64).collect(),
		gradient_to_host,
		gradient_to_primary: Transfer { from: 0, to: 1, bytes: gradient_bytes, cost: links[route[0]].from_host },
		weights_to_host: Transfer { from: 1, to: 0, bytes: weight_bytes, cost: links[route[0]].to_host },
		weights_from_host,
		loss,
		predicted: [0.0; 4],
	};
	let bandwidth = |transfer: &Transfer| transfer.bytes as f64 / transfer.cost.bandwidth;
	// Shards compute their gradients concurrently, so the slowest shard sets the
	// route's gradient time, and the leading device adds the one optimizer update.
	let computation = route.iter().zip(&counts).map(|(device, count)| Ok(gradient_work(graph, *count)? / links[*device].work)).collect::<Result<Vec<_>>>()?.into_iter().fold(0.0, f64::max)
		+ optimizer_work(graph) / links[route[0]].work;
	let transfers = placement.gradient_to_host.iter().map(bandwidth).sum::<f64>() + bandwidth(&placement.gradient_to_primary);
	let movement = bandwidth(&placement.weights_to_host) + placement.weights_from_host.iter().map(bandwidth).sum::<f64>();
	let synchronization = route.iter().map(|device| links[*device].overhead).sum::<f64>() + placement.movements().map(|transfer| transfer.cost.latency.as_secs_f64()).sum::<f64>();
	Ok((counts, Placement { predicted: [computation, transfers, synchronization, movement], ..placement }))
}
/// Selects the route this run trains on. `multi-device = false` keeps the
/// local device, `true` forces every selected device, and `"auto"` predicts the
/// complete epoch of every valid candidate route from the established workload,
/// the storage plan, and measured device behavior, then takes the lowest. No
/// policy allocates or dispatches the model being placed to decide.
fn select_route(gpus: &'static [&'static Gpu], graph: &Graph, rows: usize, loss: LossFunction, config: Config) -> Result<(Vec<usize>, Vec<usize>, Placement)> {
	let bytes = graph.nodes.iter().try_fold((0, 0), |(gradients, weights), node| {
		let state = NativePrecision::new(node.precision, node.acc)?.state;
		Ok::<_, RecipeError>((checked_add(gradients, checked_mul(node.parameters, state.bytes(), "gradient transfer")?, "gradient transfers")?, checked_add(weights, checked_mul(node.parameters, node.precision.bytes(), "weight transfer")?, "weight transfers")?))
	})?;
	if gpus.len() == 1 {
		let zero = TransferCost { latency: Duration::ZERO, bandwidth: f64::INFINITY };
		return Ok((
			vec![0],
			vec![rows],
			Placement {
				shares: vec![1.0],
				gradient_to_host: vec![Transfer { from: 1, to: 0, bytes: bytes.0, cost: zero }],
				gradient_to_primary: Transfer { from: 0, to: 1, bytes: bytes.0, cost: zero },
				weights_to_host: Transfer { from: 1, to: 0, bytes: bytes.1, cost: zero },
				weights_from_host: Vec::new(),
				loss,
				predicted: [0.0; 4],
			},
		));
	}
	let links = LINKS.get_or_init(|| gpus.iter().map(|gpu| measure_link(gpu, config)).collect()).as_ref().map_err(Clone::clone)?;
	let candidates: Vec<Vec<usize>> = match config.multi_device {
		MultiDevice::Local => vec![vec![0]],
		MultiDevice::Forced => vec![(0..gpus.len()).collect()],
		MultiDevice::Auto => (1..1_u64 << gpus.len()).map(|mask| (0..gpus.len()).filter(|device| mask >> device & 1 == 1).collect()).collect(),
	};
	let mut best: Option<(Vec<usize>, Vec<usize>, Placement)> = None;
	for mut route in candidates.into_iter().filter(|route| route.len() <= rows) {
		// The fastest device leads the route and applies the one update.
		route.sort_by(|left, right| links[*right].work.total_cmp(&links[*left].work).then(left.cmp(right)));
		let (counts, placement) = plan_route(&route, &links, graph, rows, bytes, loss, config.multi_device)?;
		best = if best.as_ref().is_none_or(|previous| placement.seconds() < previous.2.seconds()) { Some((route, counts, placement)) } else { best };
	}
	best.ok_or_else(|| RecipeError::new("no candidate route fits this workload"))
}
/// A training tape placed across the selected device topology. One device
/// trains through the same gradient and optimizer entrypoints. Across several
/// devices the rows shard contiguously, every device computes a gradient, the
/// primary device applies the one emitted optimizer, and its weights broadcast.
struct DeviceTape {
	devices: Vec<&'static Gpu>,
	route: Vec<usize>,
	shards: Vec<NativeTape>,
	placement: Placement,
}
impl DeviceTape {
	fn capture_tensors(&self) -> Result<Vec<TensorObservation>> {
		let (mut tensors, mut row_start) = (Vec::new(), 0);
		for shard in &self.shards {
			let mut captured = shard.capture_tensors(0, shard.positions)?;
			for tensor in &mut captured { tensor.row_start = row_start; }
			tensors.extend(captured);
			row_start = checked_add(row_start, shard.rows as usize, "tensor observation row range")?;
		}
		Ok(tensors)
	}
	fn llvm_report(&self) -> LlvmReport {
		let mut report = LlvmReport::default();
		for shard in &self.shards {
			report.instructions.extend(shard.program.artifact.llvm.instructions.clone());
			report.intrinsics.extend(shard.program.artifact.llvm.intrinsics.clone());
		}
		report
	}
	fn format_report(&self) -> Result<ReportLines> {
		Ok(ReportLines::new(self.shards.iter().map(NativeTape::format_lines).collect::<Result<Vec<_>>>()?.into_iter().flatten()))
	}
	fn memory_report(&self) -> Result<ReportLines> {
		let mut lines = Vec::with_capacity(self.devices.len());
		for (index, gpu) in self.devices.iter().enumerate() {
			if let Some(position) = self.route.iter().position(|selected| *selected == index) {
				lines.push(self.shards[position].memory_line()?);
			} else {
				lines.push(format!("{}  memory: input 0 bytes weights 0 bytes values 0 bytes contexts 0 bytes adjoints 0 bytes gradients 0 bytes optimizer 0 bytes load-scratch 0 bytes", device_label(gpu)?));
			}
		}
		Ok(ReportLines::new(lines))
	}
	fn link_report(&self) -> Result<ReportLines> { transfer_report(self.shards.iter().map(|shard| shard.program.gpu)) }
	fn aot_report(&self) -> Result<ReportLines> {
		let mut lines = Vec::with_capacity(self.devices.len());
		for (index, gpu) in self.devices.iter().enumerate() {
			if let Some(position) = self.route.iter().position(|selected| *selected == index) {
				let shard = &self.shards[position];
				lines.push(format!("{}  aot: rows {} share {:.6} predicted epoch {:.3} µs", device_label(gpu)?, shard.rows, self.placement.shares[position], self.placement.seconds() * 1e6));
			} else {
				lines.push(format!("{}  aot: rows 0 share 0.000000", device_label(gpu)?));
			}
		}
		Ok(ReportLines::new(lines))
	}
	fn tile_report(&self) -> Result<ReportLines> {
		Ok(ReportLines::new(self.shards.iter().map(NativeTape::tile_lines).collect::<Result<Vec<_>>>()?.into_iter().flatten()))
	}
	fn grid_report(&self) -> Result<ReportLines> {
		Ok(ReportLines::new(self.shards.iter().map(NativeTape::grid_lines).collect::<Result<Vec<_>>>()?.into_iter().flatten()))
	}
	fn compile_seconds(&self) -> f64 { self.shards.iter().map(|shard| shard.compile_seconds).sum() }
	fn load_seconds(&self) -> f64 { self.shards.iter().map(|shard| shard.load_seconds).sum() }
	fn new(graph: &Graph, samples: &[f64], targets: &[f64], gpus: &'static [&'static Gpu], precision: Compute, loss: LossFunction, config: Config) -> Result<Self> {
		// Validate and resolve training before route calibration builds any kernels.
		let training_graph = graph.training_graph()?;
		let graph = training_graph.as_ref();
		let precision = if graph.profile.train == Some(Compute::FP64) && graph.nodes.iter().any(|node| node.int_bits != 0) { Compute::FP64 } else { precision };
		let (input, output) = (graph.input.elements(), graph.output.elements());
		require(input != 0 && samples.len() % input == 0, "model input batch is not a whole number of rows")?;
		let rows = samples.len() / input;
		require(!targets.is_empty(), "training requires targets")?;
		require(
			gpus.len() == 1 || !graph.nodes.iter().any(|node| node.op == Primitive::Normalize && node.argument[0] == 0.0),
			"batch normalization computes whole-batch statistics, so this model trains on one device",
		)?;
		let (route, counts, placement) = select_route(gpus, graph, rows, loss, config)?;
		let (mut shards, mut start) = (Vec::new(), 0);
		for (device, count) in route.iter().zip(&counts) {
			let end = start + count;
			shards.push(NativeTape::new(
				graph,
				TapeInput::Values(&samples[start * input..end * input]),
				&samples[start * input..end * input],
				&targets[start * output..end * output],
				gpus[*device],
				precision,
				Some(loss),
			)?);
			start = end;
		}
		Ok(Self { devices: gpus.to_vec(), route, shards, placement })
	}
	fn forward(&mut self) -> Result<()> {
		self.shards.iter().try_for_each(|tape| tape.forward(ForwardMode::Inference))
	}
	fn metrics(&mut self, config: Config) -> Result<EpochMetrics> {
		let transfers = TransferScope::current();
		let parts = std::thread::scope(|scope| {
			let measured = self.shards.iter_mut().map(|shard| {
				let transfers = transfers.clone();
				scope.spawn(move || { let _transfers = TransferScope::enter(transfers); shard.metric_launch(config) })
			}).collect::<Vec<_>>();
			measured.into_iter().map(|part| part.join().map_err(|_| RecipeError::new("device metrics panicked"))?).collect::<Result<Vec<_>>>()
		})?;
		let root_loss = self.placement.loss.0 == 1;
		Ok(EpochMetrics::combine(parts.into_iter().zip(self.placement.shares.iter().copied()), root_loss))
	}
	fn predictions(&self) -> Result<Vec<f64>> {
		let mut predictions = Vec::new();
		for shard in &self.shards {
			predictions.extend(shard.predictions()?);
		}
		Ok(predictions)
	}
	fn evaluate(&mut self, graph: &Graph, samples: &[f64], targets: &[f64], first: usize, loss: LossFunction, config: Config) -> Result<(Vec<f64>, EpochMetrics)> {
		self.shards.first_mut().ok_or_else(|| RecipeError::new("training placement has no device"))?.evaluate(graph, samples, targets, first, loss, config)
	}
	fn inject_bn_stats(&self, stats: &[f64]) -> Result<()> {
		if self.shards.len() > 1 {
			return require(stats.is_empty(), "batch normalization statistics cannot place across devices");
		}
		self.shards[0].inject_bn_stats(stats)
	}
	/// Recompute batch statistics using the current weights before saving.
	fn extract_bn_stats(&mut self) -> Result<Vec<f64>> {
		if self.shards.len() > 1 {
			return Ok(Vec::new());
		}
		let shard = &mut self.shards[0];
		if !shard.batch_normalizations.is_empty() {
			shard.forward(ForwardMode::Training)?;
		}
		shard.extract_bn_stats()
	}
	fn advance(&mut self) -> Result<()> {
		self.shards.iter_mut().try_for_each(NativeTape::advance)
	}
	fn step(&self) -> u32 {
		self.shards[0].step
	}
	fn best_loss(&self) -> [f64; 4] {
		self.shards[0].best_loss
	}
	fn tile(&self) -> Tile {
		self.shards[0].tile()
	}
	/// Cap total tuning launches by the requested epoch count.
	fn tune(&mut self, rate: f64, epochs: usize, config: Config) -> Result<()> {
		let budget = config.schedule_budget.min(epochs);
		if config.schedule_candidates == 0 || budget == 0 {
			return Ok(());
		}
		let shard_count = self.shards.len();
		let base = budget / shard_count;
		let remainder = budget % shard_count;
		for (index, shard) in self.shards.iter_mut().enumerate() {
			let mut budget = base + usize::from(index < remainder);
			trace(&format!("schedule budget device={} launches={budget}", shard.device_label()?))?;
			tune_contraction_schedule(shard, rate, config, &mut budget)?;
		}
		Ok(())
	}
	fn schedule(&self) -> String {
		if self.shards.len() == 1 {
			return self.shards[0].schedule();
		}
		self.shards
			.iter()
			.map(|shard| format!("{}={}", shard.device_label().unwrap_or_else(|_| shard.program.gpu.name.clone()), shard.schedule()))
			.collect::<Vec<_>>()
			.join(" ")
	}
	/// The one fused epoch every policy runs: each shard computes its gradient
	/// concurrently, the leading device applies the one emitted optimizer to the
	/// aggregate, and the updated persistent weights return to every shard.
	fn epoch(&mut self, rate: f64, tolerance: f64, config: Config) -> Result<(EpochMetrics, bool)> {
		if self.shards.len() == 1 {
			let loss = self.shards[0].full_epoch(rate, config)?;
			let checkpoint_requested = observe_loss(&mut self.shards[0].best_loss, loss, tolerance);
			return Ok((self.shards[0].epoch_metrics()?, checkpoint_requested));
		}
		let placement = &self.placement;
		let shards = &mut self.shards;
		let transfers = TransferScope::current();
		let measured = std::thread::scope(|scope| {
			let dispatched = shards.iter_mut().zip(&placement.gradient_to_host).map(|(shard, transfer)| {
				let transfer = *transfer;
				let transfers = transfers.clone();
				scope.spawn(move || -> Result<(EpochMetrics, Vec<f64>)> {
					let _transfers = TransferScope::enter(transfers);
					require(transfer.to == 0, "gradient transfer must end on the master")?;
					shard.gradient_launch(rate, config)?;
					Ok((shard.epoch_metrics()?, shard.download_gradient()?))
				})
			});
			dispatched.collect::<Vec<_>>().into_iter().map(|shard| shard.join().map_err(|_| RecipeError::new("device epoch panicked"))?).collect::<Result<Vec<_>>>()
		})?;
		let root_metric = placement.loss.0 == 1;
		let mut metrics = EpochMetrics::combine(measured.iter().zip(&placement.shares).map(|((metrics, _), share)| (*metrics, *share)), root_metric);
		let loss = metrics.loss;
		let parameters = self.shards[0].parameters;
		let mut gradient = vec![0.0; parameters];
		for ((metrics, shard_gradient), share) in measured.iter().zip(&placement.shares) {
			// The RMSE seed divides by the shard-local loss, so restoring the
			// whole-batch gradient rescales each shard by its loss ratio.
			let scale = share * if root_metric { if loss == 0.0 { 0.0 } else { metrics.loss / loss } } else { 1.0 };
			for (total, partial) in gradient.iter_mut().zip(shard_gradient) {
				*total += scale * partial;
			}
		}
		require(
			placement.gradient_to_primary.from == 0 && placement.gradient_to_primary.to == 1 && placement.weights_to_host.from == 1 && placement.weights_to_host.to == 0,
			"the aggregate gradient and the updated weights must cross the master",
		)?;
		self.shards[0].upload_gradient(&gradient)?;
		self.shards[0].optimizer_launch(rate, config)?;
		metrics.device_seconds += f64::from_bits(self.shards[0].last_device_seconds.load(Ordering::Acquire));
		let weights = self.shards[0].weights()?;
		for (shard, transfer) in self.shards.iter().skip(1).zip(&placement.weights_from_host) {
			require(transfer.from == 0, "weight transfer must originate on the master")?;
			shard.upload_weights(&weights)?;
		}
		let checkpoint_requested = observe_loss(&mut self.shards[0].best_loss, loss, tolerance);
		Ok((metrics, checkpoint_requested))
	}
	fn weights(&self) -> Result<Vec<f64>> {
		self.shards[0].weights()
	}
	fn capture(&self, graph: &mut Graph) -> Result<()> {
		self.shards[0].capture(graph)
	}
}

fn training_observability(
	data: &Data,
	rows: usize,
	tape: &DeviceTape,
	itl: TrainingPoint,
	loss: ScalarHistory,
	predictions: PredictionHistory,
	r2: ScalarHistory,
	rat: RatHistory,
	fnl: TrainingPoint,
	epochs: usize,
	epoch_seconds: f64,
) -> Result<TrainingObservability> {
	Ok(TrainingObservability {
		tensors: Vec::new(),
		llvm: tape.llvm_report(),
		path: data.report_path()?,
		rows,
		formats: tape.format_report()?,
		memory: tape.memory_report()?,
		links: tape.link_report()?,
		aot: tape.aot_report()?,
		tiles: tape.tile_report()?,
		grids: tape.grid_report()?,
		load: DurationReport(tape.load_seconds()),
		compile: DurationReport(tape.compile_seconds()),
		itl,
		loss,
		predictions,
		r2,
		rat,
		fnl,
		eps: if epoch_seconds == 0.0 { 0.0 } else { epochs as f64 / epoch_seconds },
	})
}

fn single_training_observability(
	path: String,
	rows: usize,
	tape: &NativeTape,
	_link: Option<Link>,
	predicted_epoch: Option<f64>,
	itl: TrainingPoint,
	loss: ScalarHistory,
	predictions: PredictionHistory,
	r2: ScalarHistory,
	rat: RatHistory,
	fnl: TrainingPoint,
	epochs: usize,
	epoch_seconds: f64,
) -> Result<TrainingObservability> {
	let device = tape.device_label()?;
	let links = transfer_report([tape.program.gpu])?;
	Ok(TrainingObservability {
		tensors: Vec::new(),
		llvm: tape.llvm_report(),
		path,
		rows,
		formats: ReportLines::new(tape.format_lines()?),
		memory: ReportLines::new([tape.memory_line()?]),
		links,
		aot: ReportLines::new([predicted_epoch.map_or_else(|| format!("{device}  aot: rows {rows}"), |seconds| format!("{device}  aot: rows {rows} predicted epoch {:.3} µs", seconds * 1e6))]),
		tiles: ReportLines::new(tape.tile_lines()?),
		grids: ReportLines::new(tape.grid_lines()?),
		load: DurationReport(tape.load_seconds),
		compile: DurationReport(tape.compile_seconds),
		itl,
		loss,
		predictions,
		r2,
		rat,
		fnl,
		eps: if epoch_seconds == 0.0 { 0.0 } else { epochs as f64 / epoch_seconds },
	})
}
#[derive(Clone, Copy)]
enum CheckpointStatus {
	Saved,
	Kept,
}
fn checkpoint(path: &Path, schema: &DataSchema, stored: &mut bundle::StoredGraph, tape: &DeviceTape) -> Result<CheckpointStatus> {
	if let Ok((_, saved)) = bundle::load_semantic(path) {
		if saved.first().and_then(|g| g.state.best_loss.first().copied()).is_some_and(|v| v <= tape.best_loss()[0]) {
			return Ok(CheckpointStatus::Kept);
		}
	}
	tape.capture(&mut stored.graph)?;
	bundle::save_semantic(path, schema, std::slice::from_mut(stored))?;
	Ok(CheckpointStatus::Saved)
}
fn structural(value: f64) -> Result<i32> {
	require(value.is_finite() && value.fract() == 0.0 && value >= f64::from(i32::MIN) && value <= f64::from(i32::MAX), "node structural argument is invalid").map(|_| value as i32)
}
fn graph_rows_buffer(shape: Shape, rows: usize, element: usize) -> Result<usize> {
	checked_mul(checked_mul(rows, shape.elements(), "node elements")?, element, "node bytes")
}
/// The inference attention carry stores only the key and value planes for every
/// settled position. Queries remain in the ordinary source window.
fn attention_kv_bytes(node: &Node, rows: usize, precision: Compute) -> Result<usize> {
	let heads = integer_argument(node.argument[0], "attention heads")? as usize;
	let kv = integer_argument(node.argument[1], "attention key-value heads")? as usize;
	require(heads != 0 && kv != 0 && heads % kv == 0, "attention key-value head partition is invalid")?;
	require(node.output.channels % heads == 0, "attention channels do not divide query heads")?;
	let width = node.output.channels / heads;
	let elements = checked_mul(
		checked_mul(rows, checked_mul(kv + attention_value_heads(node), width, "attention K/V channels")?, "attention K/V planes")?,
		node.output.length,
		"attention K/V positions",
	)?;
	checked_mul(elements, precision.bytes(), "attention K/V bytes")
}
// An embedding row is addressed inside the packed table, so the row must span
// whole blocks and the layout must keep one row's blocks together.
fn embedding_row(node: &Node) -> Result<(&'static Quantization, usize)> {
	let format = StorageFormat(node.storage);
	let layout = format.spec().ok_or_else(|| RecipeError::new("embedding table must be stored in a quantization"))?.codec.quantization();
	require(!matches!(layout.native, NativeDequant::Nf4), format!("embedding table cannot use {}: its codebook addresses the whole tensor", layout.name))?;
	let width = integer_argument(node.argument[1], "embedding width")? as usize;
	require(width % layout.block == 0, format!("embedding width {width} must be a multiple of the {} block of {}", layout.name, layout.block))?;
	checked_mul(width / layout.block, layout.stride, "embedding row bytes").map(|row| (layout, row))
}
// A table is decoded one row at a time, from the context arena or on the host,
// so it is absent from the storage the model-load kernel expands into weights.
fn arena_weight<'a>(node: &Node, stored: &'a Option<StoredWeight>) -> Option<&'a StoredWeight> {
	stored.as_ref().filter(|_| !node.table())
}
/// Positions of its source a node reads behind the window it writes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum History {
	/// The node reads only the positions it writes.
	None,
	/// The node reads that many positions before the window.
	Positions(usize),
	/// The node reads every position the sequence has settled.
	Sequence,
}
/// What one node carries across the positions of a sequence: the positions of
/// its source a step reads behind the window it writes, and the values it keeps
/// in its own context for the whole sequence. Every arena a decode step reads is
/// named here rather than inferred from the emitters, so the step, the placement
/// and any arena that reuses dead spans read one description.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Carried {
	history: History,
	values: usize,
}
impl Carried {
	const NONE: Self = Self { history: History::None, values: 0 };
	/// Whether the node carries anything at all across positions.
	fn any(self) -> bool {
		self.history != History::None || self.values != 0
	}
}
/// The state `node` declares for one sequence of `rows` rows. Attention reads
/// the keys and values of every settled position, a scan its previous output and
/// cell, a delta rule its previous state, a convolution the `kernel - 1` earlier
/// positions its taps span and a depthwise one the `(kernel - 1) * dilation` its
/// dilated taps span, a pool every position it reduces, a per-layer embedding the
/// rows the host staged for every settled position, and an evaluation
/// normalization the statistics its training saved.
fn carried(node: &Node, rows: usize) -> Result<Carried> {
	let carried = match node.op {
		// Softmax statistics per query and head, then the indexer's block
		// representatives, both written as the positions settle.
		Primitive::Attention => {
			let queries = checked_mul(rows, node.output.length, "attention statistics rows")?;
			let statistics = checked_mul(checked_mul(queries, node.argument[0] as usize, "attention statistics heads")?, 2, "attention statistics")?;
			let representatives = checked_mul(checked_mul(rows, attention_blocks(node), "indexer block rows")?, node.argument[6] as usize, "indexer representatives")?;
			let (keys, counts) = attention_index_state(node, rows)?;
			let scores = checked_mul(queries, checked_mul(attention_blocks(node), 2, "indexer score row")?, "indexer scores")?;
			let prefix = checked_add(checked_add(statistics, representatives, "attention state")?, scores, "indexer score state")?;
			let count_values = checked_mul(counts, size_of::<u64>() / node.precision.bytes(), "indexer count storage")?;
			let cache = checked_add(checked_mul(keys, 3, "indexer raw, representative, and sum caches")?, count_values, "indexer cached state")?;
			Carried { history: History::Sequence, values: checked_add(prefix, cache, "attention carried state")? }
		}
		Primitive::Scan => {
			let (state_count, gates) = (checked_mul(rows, node.output.elements(), "scan batch")?, node.argument[0] as usize);
			Carried { history: History::Positions(1), values: checked_mul(gates + 1, state_count, "scan states")? }
		}
		// One thread owns one row and head: the chunk entry states, the live state
		// and the chunk the reverse pass replays.
		Primitive::Delta => {
			let (_, key_width, heads, width) = delta_extent(node).map(|(a, b, c, d)| (a as usize, b as usize, c as usize, d as usize))?;
			let (chunk, state) = ((node.argument[2] as usize).max(1), checked_mul(key_width, width, "delta state")?);
			let spans = checked_add(node.output.length.div_ceil(chunk), checked_add(chunk, 1, "delta live states")?, "delta state spans")?;
			let states = checked_mul(checked_mul(rows, heads, "delta pairs")?, checked_mul(spans, state, "delta state span")?, "delta states")?;
			Carried { history: History::Positions(1), values: states }
		}
		// Tap `j` of a `kernel`-wide depthwise convolution reads the position
		// `(kernel - 1 - j) * dilation` behind, so its tail is that many positions.
		Primitive::Dconv => {
			let (kernel, dilation) = (integer_argument(node.argument[0], "depthwise kernel")? as usize, integer_argument(node.argument[1], "depthwise dilation")?.max(1) as usize);
			Carried { history: History::Positions(checked_mul(kernel.saturating_sub(1), dilation, "depthwise tail")?), values: 0 }
		}
		Primitive::Contraction if node.argument[0] > 1.0 => Carried { history: History::Positions(integer_argument(node.argument[0], "contraction kernel")? as usize - 1), values: 0 },
		Primitive::Pool => Carried { history: History::Sequence, values: checked_mul(rows, node.output.elements(), "pool context")? },
		// The rows the host gathers for every position, staged as [row][position][channel].
		Primitive::Lookup => Carried { history: History::Sequence, values: checked_mul(rows, node.output.elements(), "lookup staging")? },
		// A batch normalization keeps the mean and variance its training saved at
		// the head of its statistics span, so they cross into inference rather than
		// across the positions of a sequence.
		Primitive::Normalize if normalize_mode(node.argument[0])? == program_ir::NormalizeMode::Batch => {
			Carried { history: History::None, values: checked_mul(2, node.output.channels, "normalization statistics")? }
		}
		_ => Carried::NONE,
	};
	Ok(carried)
}
/// The nodes that carry state across the positions of a sequence, with what each
/// one declares. The placement counts it, a step reads it, and a tape restores
/// the statistics an evaluation normalization saved out of it.
fn carried_state(nodes: &[Node], rows: usize) -> Result<Vec<(usize, Carried)>> {
	let mut declared = Vec::new();
	for (index, node) in nodes.iter().enumerate() {
		let state = carried(node, rows)?;
		if state.any() {
			declared.push((index, state));
		}
	}
	Ok(declared)
}
const NEAREST_LEAF_ROWS: usize = 16;
const NEAREST_NODE_FIELDS: usize = 5;
fn nearest_rows(parameters: usize, features: usize) -> Option<usize> {
	features.checked_add(1).and_then(|width| parameters.checked_div(width).filter(|rows| *rows != 0 && *rows * width == parameters))
}
#[rustfmt::skip]
fn nearest_index_shape(rows: usize, features: usize) -> Option<(usize, usize)> { Some((rows.div_ceil(NEAREST_LEAF_ROWS).checked_next_power_of_two()?.checked_mul(2)?.checked_sub(1)?, features.checked_mul(2)?.checked_add(NEAREST_NODE_FIELDS)?)) }
#[rustfmt::skip]
fn nearest_layout(node: &Node, programs: &[f64]) -> Result<Option<(usize, usize, usize)>> {
	if node.op != Primitive::Predictor { return Ok(None) }
	let end = node.program_offset.checked_add(checked_mul(node.program_count, 2, "predictor program")?).ok_or_else(|| RecipeError::new("predictor program range overflows"))?;
	let program = programs.get(node.program_offset..end).ok_or_else(|| RecipeError::new("predictor program range is invalid"))?;
	if !program.chunks_exact(2).any(|instruction| instruction[0] == PredictorOpcode::Nearest as i32 as f64) { return Ok(None) }
	let table_rows = nearest_rows(node.parameters, node.input.elements()).ok_or_else(|| RecipeError::new("nearest table width is invalid"))?;
	let (nodes, stride) = nearest_index_shape(table_rows, node.input.elements()).ok_or_else(|| RecipeError::new("nearest index size overflows"))?;
	Ok(Some((node.input.elements(), table_rows, checked_mul(checked_add(checked_mul(nodes, stride, "nearest index fields")?, table_rows, "nearest index values")?, size_of::<u32>(), "nearest index bytes")?)))
}
/// Context regions in model elements, including which forward data survives
/// the next window and which storage only the backward pass uses.
fn recurrent_body_regions(graph: &Graph, node: &Node, rows: usize, inference: bool, step: usize) -> Result<Option<Vec<(usize, BufferLifetime)>>> {
	if node.op != Primitive::Scan || node.argument[5] != 1.0 {
		return Ok(None);
	}
	let start = usize::try_from(integer_argument(node.argument[3], "recurrent body start")?).map_err(|_| RecipeError::new("recurrent body start is invalid"))?;
	let count = usize::try_from(integer_argument(node.argument[4], "recurrent body count")?).map_err(|_| RecipeError::new("recurrent body count is invalid"))?;
	let end = start.checked_add(count).ok_or_else(|| RecipeError::new("recurrent body range overflows"))?;
	require(count != 0 && end <= graph.nodes.len(), "recurrent body range is invalid")?;
	let layout = recur_body_layout(node, &graph.nodes[start..end], rows)?;
	if !inference { return Ok(Some(vec![(layout.total.max(1), BufferLifetime::Retained)])); }
	let local = BufferLifetime::Until(step);
	let state_count = checked_mul(rows, node.output.elements(), "scan batch")?;
	let gates = checked_mul(node.argument[0] as usize, state_count, "recurrent gate context")?;
	let forward = checked_add(gates, state_count, "recurrent forward context")?;
	// The body tapes count bytes; the regions count the scan's elements.
	let (values, adjoints) = (layout.values / node.precision.bytes(), layout.adjoints / node.precision.bytes());
	Ok(Some(vec![
		(gates, local),
		(state_count, if node.argument[0] == 4.0 { BufferLifetime::Retained } else { BufferLifetime::Unused }),
		(layout.base - forward, BufferLifetime::Unused),
		(layout.cell, local),
		(values - layout.cell_values, BufferLifetime::Retained),
		(adjoints - values, local),
		(layout.total - adjoints, BufferLifetime::Unused),
	]))
}
fn backward_context_offset(node: &Node, rows: usize) -> Result<usize> {
	let elements = match node.op {
		Primitive::Scan => checked_mul(checked_mul(node.argument[0] as usize + 1, rows, "scan forward rows")?, node.output.elements(), "scan forward states")?,
		Primitive::Delta => {
			let (_, key_width, heads, width) = delta_extent(node).map(|(a, b, c, d)| (a as usize, b as usize, c as usize, d as usize))?;
			let chunk = (node.argument[2] as usize).max(1);
			let spans = checked_add(node.output.length.div_ceil(chunk), checked_add(chunk, 1, "delta forward spans")?, "delta forward spans")?;
			checked_mul(checked_mul(rows, heads, "delta pairs")?, checked_mul(spans, checked_mul(key_width, width, "delta state")?, "delta forward states")?, "delta forward context")?
		}
		_ => return Err(RecipeError::new("this op has no separate backward context")),
	};
	let state_bytes = NativePrecision::new(node.precision, node.acc)?.state.bytes();
	let element_bytes = if node.op == Primitive::Delta { state_bytes } else { node.precision.bytes() };
	align(checked_mul(elements, element_bytes, "forward context bytes")?, state_bytes)
}
fn backward_context_bytes(node: &Node, rows: usize) -> Result<usize> {
	let elements = match node.op {
		Primitive::Scan => {
			let deltas = checked_mul(checked_mul(rows, node.output.elements(), "scan batch")?, node.argument[0] as usize, "scan gate derivatives")?;
			let gradients = checked_mul(rows, node.parameters, "scan gradient partials")?;
			let scratch = checked_mul(2, checked_mul(rows, node.output.channels, "scan scratch rows")?, "scan scratch")?;
			checked_add(deltas, checked_add(gradients, scratch, "scan backward scratch")?, "scan backward context")?
		}
		Primitive::Delta => {
			let (_, key_width, heads, width) = delta_extent(node).map(|(a, b, c, d)| (a as usize, b as usize, c as usize, d as usize))?;
			let state = checked_mul(key_width, width, "delta adjoint state")?;
			let vectors = checked_add(checked_mul(2, width, "delta adjoint vectors")?, 1, "delta decay partial")?;
			checked_mul(checked_mul(rows, heads, "delta backward pairs")?, checked_add(state, vectors, "delta backward pair")?, "delta backward context")?
		}
		_ => return Err(RecipeError::new("this op has no separate backward context")),
	};
	checked_mul(elements, NativePrecision::new(node.precision, node.acc)?.state.bytes(), "backward context bytes")
}
/// Context sizing and lifetimes are one declaration consumed by allocation.
/// Regions remain contiguous and in the order the kernel reads them.
fn node_context(graph: &Graph, node: &Node, rows: usize, precision: Compute, inference: bool, step: usize) -> Result<Vec<(usize, BufferLifetime)>> {
	use BufferLifetime::{ReadOnly, Retained, Unused};
	let local = if inference { BufferLifetime::Until(step) } else { Retained };
	let unused = if inference { Unused } else { Retained };
	if let Some((_, _, bytes)) = nearest_layout(node, &graph.programs)?.filter(|_| precision.pack(f64::MAX) != precision.pack(0.0)) {
		return Ok(vec![(bytes, ReadOnly)]);
	}
	if let Some(regions) = recurrent_body_regions(graph, node, rows, inference, step)? {
		return regions.into_iter().map(|(elements, lifetime)| Ok((checked_mul(elements, precision.bytes(), "recurrent body context bytes")?, lifetime))).collect();
	}
	let state = carried(node, rows)?.values;
	let regions = match node.op {
		// One scratch row per reduction partition, holding this node's trainable
		// scalars. Programs without trainable scalars reduce nothing and take the
		// minimum allocation below. Only the reverse pass fills the rows.
		Primitive::Elementwise if inference => vec![(precision.bytes(), Unused)],
		Primitive::TopK => {
			let slots = checked_add(integer_argument(node.argument[0], "selected expert count")? as usize, 1, "selected expert record")?;
			let records = checked_mul(rows, node.output.length, "selected expert positions")?;
			let bytes = checked_mul(checked_mul(records, slots, "selected expert indices")?, size_of::<u32>(), "selected expert bytes")?;
			let last = graph.nodes.iter().enumerate().filter(|(_, consumer)| consumer.second == (step / 2) as i32).map(|(index, _)| index * 2 + 1).max().unwrap_or(step);
			vec![(bytes, if inference { BufferLifetime::Until(last) } else { Retained })]
		}
		Primitive::Elementwise => {
			let partials = checked_mul(checked_mul(rows, node.output.elements(), "program batch")?.min(NATIVE_SCALAR_PARTITIONS), node.parameters, "scalar gradient partials")?;
			vec![(checked_mul(partials.max(1), NativePrecision::new(node.precision, node.acc)?.state.bytes(), "scalar gradient partial bytes")?, Retained)]
		}
		Primitive::Predictor => {
			let elements = checked_mul(checked_add(node.argument[0] as usize, node.argument[1] as usize, "predictor workspace")?, rows, "predictor batch")?;
			vec![(checked_mul(elements.max(1), precision.bytes(), "predictor workspace bytes")?, local)]
		}
		// Softmax statistics, then the indexer block representatives, then one
		// row of block scores and one admission flag per block per query, then
		// raw keys, causal representatives, and filled counts.
		Primitive::Attention => {
			let (queries, blocks) = (checked_mul(rows, node.output.length, "attention statistics rows")?, attention_blocks(node));
			let statistics = checked_mul(checked_mul(queries, node.argument[0] as usize, "attention statistics heads")?, 2, "attention statistics")?;
			let representatives = checked_mul(checked_mul(rows, blocks, "indexer block rows")?, node.argument[6] as usize, "indexer representatives")?;
			let scores = checked_mul(queries, checked_mul(blocks, 2, "indexer score row")?, "indexer scores")?;
			let (keys, counts) = attention_index_state(node, rows)?;
			let derivatives = if inference { 0 } else { checked_mul(checked_mul(queries, node.argument[0] as usize, "indexer derivative heads")?, blocks, "indexer derivatives")? };
			vec![
				(checked_mul(statistics, precision.bytes(), "attention statistics bytes")?, local),
				(checked_mul(representatives, precision.bytes(), "indexer representatives bytes")?, Retained),
				(checked_mul(scores, precision.bytes(), "indexer scores bytes")?, local),
				(checked_mul(keys, precision.bytes(), "indexer raw key bytes")?, Retained),
				(checked_mul(keys, precision.bytes(), "indexer causal representative bytes")?, Retained),
				(checked_mul(keys, precision.bytes(), "indexer causal sum bytes")?, Retained),
				(checked_mul(counts, size_of::<u64>(), "indexer filled count bytes")?, Retained),
				(checked_mul(derivatives, precision.bytes(), "indexer derivatives bytes")?, Retained),
			]
		}
		// The gate states, then the weight gradient rows only the reverse pass
		// accumulates, then the reduction scratch.
		Primitive::Scan => {
			if !inference { return Ok(vec![(checked_add(backward_context_offset(node, rows)?, backward_context_bytes(node, rows)?, "scan context")?, Retained)]); }
			let (state_count, gates) = (checked_mul(rows, node.output.elements(), "scan batch")?, node.argument[0] as usize);
			let state_bytes = checked_mul(state_count, precision.bytes(), "scan state bytes")?;
			vec![
				(checked_mul(gates, state_bytes, "scan gate bytes")?, local),
				(state_bytes, if gates == 4 { Retained } else { Unused }),
				(checked_mul(node.argument[1] as usize, state_bytes, "scan reserved bytes")?, Unused),
			]
		}
		// One thread owns one row and head: the chunk entry states, the live state,
		// the chunk the reverse pass replays, the state adjoint, the readout error
		// and key weight vectors, and one decay partial. The forward pass carries
		// the live state alone, so an inference pair holds no entry or replay span.
		Primitive::Delta => {
			if !inference { return Ok(vec![(checked_add(backward_context_offset(node, rows)?, backward_context_bytes(node, rows)?, "delta context")?, Retained)]); }
			let (_, key_width, heads, width) = delta_extent(node).map(|(a, b, c, d)| (a as usize, b as usize, c as usize, d as usize))?;
			let state = checked_mul(key_width, width, "delta state")?;
			let pair_bytes = checked_mul(checked_mul(rows, heads, "delta pairs")?, NativePrecision::new(node.precision, node.acc)?.state.bytes(), "delta pair bytes")?;
			let slots = checked_add(integer_argument(node.argument[5], "delta checkpoint slots")? as usize, 1, "delta state slots")?;
			vec![
				(checked_mul(checked_mul(pair_bytes, state, "delta carried state bytes")?, slots, "delta checkpoint bytes")?, Retained),
				(checked_mul(pair_bytes, checked_mul(3, node.output.length, "delta window scalars")?, "delta prepared bytes")?, local),
			]
		}
		Primitive::Pool if inference => Vec::new(),
		Primitive::Dconv if inference && node.input.length < graph.input.length => {
			let positions = checked_mul(checked_mul(rows, node.input.channels, "depthwise history channels")?, dconv_history(graph, node)?, "depthwise history positions")?;
			vec![(checked_mul(positions, precision.bytes(), "depthwise history bytes")?, Retained)]
		}
		Primitive::Pool => vec![(checked_mul(state, size_of::<u64>(), "pool context bytes")?, Retained)],
		Primitive::Rope => match rope_sections(node, &graph.programs)? {
			Some(layout) => vec![(checked_mul(rope_context_words(layout, rows, node.output.length)?, size_of::<i32>(), "rotary context bytes")?, ReadOnly)],
			None => Vec::new(),
		},
		// The packed embedding table is the node's persistent state: the gather
		// decodes rows out of it and never expands it into the weights.
		Primitive::Gather if inference && node.output.length < graph.input.length => vec![(8, Retained)],
		Primitive::Gather if inference => vec![(checked_mul(checked_mul(checked_mul(rows, node.argument[1] as usize, "embedding staging channels")?, node.output.length, "embedding staging positions")?, precision.bytes(), "embedding staging bytes")?, Retained)],
		Primitive::Gather => vec![(checked_mul(integer_argument(node.argument[0], "embedding vocabulary")? as usize, embedding_row(node)?.1, "embedding table bytes")?, ReadOnly)],
		Primitive::Lookup if inference && node.output.length < graph.input.length => vec![(8, Retained)],
		Primitive::Lookup => vec![(checked_mul(state.max(1), precision.bytes(), "lookup context bytes")?, Retained)],
		// One count per expert, then every routed position of every expert in
		// ascending expert and position order. Only the weight gradients walk
		// the lists, so an inference tape holds none.
		Primitive::ExpertIn | Primitive::ExpertOut if inference => vec![(precision.bytes(), Unused)],
		Primitive::ExpertIn | Primitive::ExpertOut => {
			let entries = checked_mul(checked_mul(rows, node.output.length, "routed positions")?, node.argument[1] as usize, "routed slots")?;
			vec![(checked_mul(checked_add(node.argument[0] as usize, entries, "expert bucket")?, size_of::<u32>(), "expert bucket bytes")?, Retained)]
		}
		// Four statistics per group; for an evaluation mode that span is the saved
		// mean and variance the node declares, so it is counted once.
		Primitive::Normalize => {
			if inference {
				let lifetime = match normalize_mode(node.argument[0])? {
					program_ir::NormalizeMode::Evaluation => ReadOnly,
					program_ir::NormalizeMode::Batch => Retained,
					_ => local,
				};
				return Ok(vec![(checked_mul(checked_mul(2, normalize_groups(node, rows)?, "normalization statistics")?, precision.bytes(), "normalization context")?, lifetime)]);
			}
			let partials = checked_mul(checked_mul(rows, node.output.elements(), "normalization batch")?.min(NATIVE_SCALAR_PARTITIONS), node.parameters, "normalization weight partials")?;
			let partial_bytes = checked_mul(partials, NativePrecision::new(node.precision, node.acc)?.state.bytes(), "normalization weight partial bytes")?;
			vec![(checked_add(normalize_gradient_scratch(node, rows)?, partial_bytes, "normalization context")?, Retained)]
		}
		_ => vec![(precision.bytes(), unused)],
	};
	Ok(regions)
}
fn narrow(value: usize, role: &str) -> Result<i32> {
	i32::try_from(value).map_err(|_| RecipeError::new(format!("{role} exceeds i32")))
}
struct Buffer {
	runtime: &'static Gpu,
	pointer: u64,
	bytes: usize,
}
/// Weight arenas shared across processes. `RECIPE_HOLD=<dir>` exports a CUDA IPC
/// handle for every weight arena this process fills, keeps those arenas when
/// everything else is freed, and then waits for power loss. `RECIPE_ATTACH=<dir>`
/// opens the holder's arena with the same key instead of filling a new one, so a
/// runtime starts without reading weights. A key names an arena's layout, never its bytes.
#[derive(Default)]
struct ResidentArenas {
	held: std::collections::HashSet<u64>,
	attached: std::collections::HashSet<u64>,
}
static RESIDENT: OnceLock<Mutex<ResidentArenas>> = OnceLock::new();
fn resident_arenas() -> Result<std::sync::MutexGuard<'static, ResidentArenas>> {
	RESIDENT.get_or_init(Default::default).lock().map_err(|_| RecipeError::new("resident arena registry is poisoned"))
}
fn resident_dir(name: &str) -> Option<PathBuf> {
	std::env::var_os(name).filter(|value| !value.is_empty()).map(PathBuf::from)
}
#[repr(C)]
#[derive(Clone, Copy)]
struct IpcHandle([u8; 64]);
fn resident_key(parts: impl std::hash::Hash) -> u64 {
	use std::hash::Hasher;
	let mut hasher = std::collections::hash_map::DefaultHasher::new();
	parts.hash(&mut hasher);
	hasher.finish()
}
/// A weight arena of `bytes` on `gpu`: the holder's arena under `key` when one is
/// exported, otherwise a new arena that `fill` writes. True when attached, so the
/// caller skips every write the holder already made.
fn resident_arena(gpu: &'static Gpu, key: u64, bytes: usize, fill: impl FnOnce(&Buffer) -> Result<()>) -> Result<(Buffer, bool)> {
	let bytes = bytes.max(1);
	let record_path = |dir: &Path| dir.join(format!("{}-{key:016x}.ipc", gpu.name));
	#[cfg(nvidia)]
	if let Some(dir) = resident_dir("RECIPE_ATTACH") && let Driver::Cuda(driver) = &gpu.driver && let Ok(record) = fs::read(record_path(&dir)) {
		require(record.len() == 72, format!("resident arena record {} is malformed", record_path(&dir).display()))?;
		let held = u64::from_le_bytes(record[64..72].try_into().unwrap()) as usize;
		require(held == bytes, format!("resident arena {key:016x} on {} holds {held} bytes; this placement needs {bytes}", gpu.name))?;
		let open: unsafe extern "C" fn(*mut u64, IpcHandle, u32) -> i32 = driver._runtime.function(b"cuIpcOpenMemHandle_v2\0").or_else(|_| driver._runtime.function(b"cuIpcOpenMemHandle\0"))?;
		gpu.activate()?;
		let mut pointer = 0;
		// Flag 1 enables peer access lazily, so other dies read the arena as before.
		gpu.status(unsafe { open(&mut pointer, IpcHandle(record[..64].try_into().unwrap()), 1) }, "resident arena attach")?;
		resident_arenas()?.attached.insert(pointer);
		return Ok((Buffer { runtime: gpu, pointer, bytes }, true));
	}
	let buffer = Buffer::reserve(gpu, bytes)?;
	fill(&buffer)?;
	#[cfg(nvidia)]
	if let Some(dir) = resident_dir("RECIPE_HOLD") && let Driver::Cuda(driver) = &gpu.driver {
		let export: unsafe extern "C" fn(*mut IpcHandle, u64) -> i32 = driver._runtime.function(b"cuIpcGetMemHandle\0")?;
		gpu.activate()?;
		let mut handle = IpcHandle([0; 64]);
		gpu.status(unsafe { export(&mut handle, buffer.pointer) }, "resident arena export")?;
		let mut record = handle.0.to_vec();
		record.extend_from_slice(&(bytes as u64).to_le_bytes());
		fs::create_dir_all(&dir).map_err(|error| RecipeError::new(format!("cannot create {}: {error}", dir.display())))?;
		let path = record_path(&dir);
		let part = path.with_extension("part");
		fs::write(&part, &record).and_then(|()| fs::rename(&part, &path)).map_err(|error| RecipeError::new(format!("cannot write {}: {error}", path.display())))?;
		resident_arenas()?.held.insert(buffer.pointer);
	}
	Ok((buffer, false))
}
/// The layout key of a tape's weight arena: its offsets, formats, where its stored
/// bytes come from, and its encoded parameters. Packed weight bytes are not read.
/// It hashes as a stream, so no copy of the parameters is made; the result equals
/// hashing the tuple (name, "tape", precision, inference, offsets, bytes, nodes)
/// with each node's values collected as a `Vec<u64>` of their bits.
fn weight_arena_key(gpu: &Gpu, graph: &Graph, precision: Compute, inference: bool, offsets: &[usize], bytes: usize) -> u64 {
	use std::hash::{Hash, Hasher};
	let mut hasher = std::collections::hash_map::DefaultHasher::new();
	(gpu.name.as_str(), "tape", format!("{precision:?}"), inference, offsets, bytes).hash(&mut hasher);
	// A Vec hashes as its length, then each element in turn.
	hasher.write_usize(graph.nodes.len());
	let mut chunk = Vec::with_capacity(8 << 16);
	for (index, node) in graph.nodes.iter().enumerate() {
		let stored = graph.stored.get(index).and_then(Option::as_ref).map(|weight| (weight.format.0, weight.count, weight.bytes.identity()));
		(node.op as i32, node.offset, node.parameters, node.packed, format!("{:?}", node.precision), stored).hash(&mut hasher);
		let values = graph.parameters.get(node.offset..node.offset + node.parameters).unwrap_or(&[]);
		hasher.write_usize(values.len());
		// A slice of u64 hashes as its bytes in one write; the hasher streams, so chunks give the same result.
		for part in values.chunks(1 << 16) {
			chunk.clear();
			chunk.extend(part.iter().flat_map(|value| value.to_bits().to_ne_bytes()));
			hasher.write(&chunk);
		}
	}
	hasher.finish()
}
/// `RECIPE_HOST_HOLD=<dir on tmpfs>` keeps a mapped table in a file there, so it
/// stays in RAM until power loss whichever processes come and go, and its rows
/// never cross a network mount. The first process to need it writes it once.
fn hold_host_table(mut table: StoredWeight) -> Result<StoredWeight> {
	let Some(dir) = resident_dir("RECIPE_HOST_HOLD") else { return Ok(table) };
	let (mapping, at, length) = match table.bytes.0.as_slice() {
		[StoredSegment::Mapped(mapping, at, length)] => (mapping.clone(), *at, *length),
		_ => return Ok(table),
	};
	let name = mapping.path.file_name().map_or_else(String::new, |name| name.to_string_lossy().into_owned());
	let path = dir.join(format!("{name}-{at}-{length}.bin"));
	if fs::metadata(&path).map(|meta| meta.len()).ok() != Some(length as u64) {
		let part = path.with_extension("part");
		let mut file = fs::File::create(&part).map_err(|error| RecipeError::new(format!("cannot create {}: {error}", part.display())))?;
		let mut chunk = vec![0_u8; 64 << 20];
		let mut done = 0;
		while done < length {
			let size = chunk.len().min(length - done);
			mapping.read_at(at + done, &mut chunk[..size])?;
			std::io::Write::write_all(&mut file, &chunk[..size]).map_err(|error| RecipeError::new(format!("cannot write {}: {error}", part.display())))?;
			done += size;
		}
		drop(file);
		fs::rename(&part, &path).map_err(|error| RecipeError::new(format!("cannot place {}: {error}", path.display())))?;
	}
	table.bytes = StoredBytes::mapped(&Arc::new(gguf::Mapping::open(&path)?), 0, length);
	Ok(table)
}
/// The holder's end state: every non-weight allocation is already freed, the
/// exported arenas stay, and nothing but power loss ends the process.
fn hold_forever(dir: &Path) -> Result<std::convert::Infallible> {
	#[cfg(unix)]
	unsafe {
		extern "C" fn ignore(_: i32) {}
		// SIGHUP, SIGINT and SIGTERM end nothing here.
		for number in [1, 2, 15] { signal(number, ignore); }
	}
	let ready = dir.join("READY");
	fs::write(&ready, format!("{}\n", std::process::id())).map_err(|error| RecipeError::new(format!("cannot write {}: {error}", ready.display())))?;
	println!("holding {} resident arenas in {}", resident_arenas()?.held.len(), dir.display());
	loop { std::thread::park(); }
}
/// The largest host buffer a zero fill stages at once, so an arena of any size
/// clears without a host copy of its own size.
const ZERO_FILL_BYTES: usize = 64 << 20;
impl Gpu {
	fn copy_device(&self, destination: u64, source: u64, bytes: usize) -> Result<()> {
		self.activate()?;
		unsafe {
			match &self.driver {
				Driver::Cpu => { ptr::copy(source as *const u8, destination as *mut u8, bytes); Ok(()) }
				#[cfg(nvidia)]
				Driver::Cuda(driver) => {
					self.status((driver.copy_device)(destination, source, bytes), "device copy")
				}
				#[cfg(amd)]
				Driver::Hsa(driver) => self.status((driver.copy)(destination as Ptr, source as *const c_void, bytes), "device copy"),
				Driver::Remote(remote) => {
					let mut channel = remote.channel.lock().map_err(|_| RecipeError::new("remote channel is poisoned"))?;
					channel.write_u8(REMOTE_DEVICE_COPY)?; channel.write_u64(destination)?; channel.write_u64(source)?; channel.write_u64(bytes as u64)?; channel.flush()?;
					channel.read_status("device copy")
				}
			}
		}
	}
}
impl Gpu {
	/// Copy `rows` runs of `bytes` from `source` every `source_pitch` bytes to `destination` every `destination_pitch` bytes.
	fn copy_device_strided(&self, destination: u64, destination_pitch: usize, source: u64, source_pitch: usize, bytes: usize, rows: usize) -> Result<()> {
		#[cfg(nvidia)]
		if let Driver::Cuda(driver) = &self.driver {
			self.activate()?;
			let copy = CudaCopy2d { source_x: 0, source_y: 0, source_kind: 2, source_host: ptr::null_mut(), source, source_array: ptr::null_mut(), source_pitch,
				destination_x: 0, destination_y: 0, destination_kind: 2, destination_host: ptr::null_mut(), destination, destination_array: ptr::null_mut(), destination_pitch, width: bytes, height: rows };
			return self.status(unsafe { (driver.copy_strided)(&copy) }, "strided device copy");
		}
		for row in 0..rows as u64 {
			self.copy_device(destination + row * destination_pitch as u64, source + row * source_pitch as u64, bytes)?;
		}
		Ok(())
	}
}
impl Buffer {
	fn copy_within_strided(&self, source: usize, source_pitch: usize, destination: usize, destination_pitch: usize, bytes: usize, rows: usize) -> Result<()> {
		if bytes == 0 || rows == 0 { return Ok(()); }
		if rows == 1 { return self.copy_within(source, destination, bytes); }
		require(bytes <= source_pitch && bytes <= destination_pitch, "strided device copy rows overlap")?;
		let span = |first: usize, pitch: usize| checked_add(checked_mul(rows - 1, pitch, "strided device copy span")?, checked_add(first, bytes, "strided device copy row")?, "strided device copy end");
		let (source_end, destination_end) = (span(source, source_pitch)?, span(destination, destination_pitch)?);
		require(source_end <= self.bytes && destination_end <= self.bytes, "strided device copy exceeds its buffer")?;
		require(source_end <= destination || destination_end <= source, "strided device copy regions overlap")?;
		self.runtime.copy_device_strided(self.pointer + destination as u64, destination_pitch, self.pointer + source as u64, source_pitch, bytes, rows)
	}
	fn copy_within(&self, source: usize, destination: usize, bytes: usize) -> Result<()> {
		require(checked_add(source, bytes, "device copy source")? <= self.bytes && checked_add(destination, bytes, "device copy destination")? <= self.bytes, "device copy exceeds its buffer")?;
		if bytes == 0 || source == destination { return Ok(()); }
		require(source + bytes <= destination || destination + bytes <= source, "device copy regions overlap")?;
		self.runtime.copy_device(self.pointer + destination as u64, self.pointer + source as u64, bytes)
	}
}
impl Buffer {
	/// Copy bytes after the caller has synchronized the completed pass.
	fn download_completed_bytes(&self, offset: usize, count: usize) -> Result<Vec<u8>> {
		require(checked_add(offset, count, "tensor observation read")? <= self.bytes, "tensor observation exceeds its value buffer")?;
		let mut bytes = Vec::new();
		bytes.try_reserve_exact(count).map_err(|_| RecipeError::new("cannot allocate tensor observation bytes"))?;
		bytes.resize(count, 0);
		self.runtime.download(bytes.as_mut_ptr().cast(), self.pointer + offset as u64, count)?;
		Ok(bytes)
	}
	fn upload<T>(runtime: &'static Gpu, values: &[T]) -> Result<Self> {
		let bytes = size_of_val(values);
		Ok(Self { runtime, pointer: runtime.upload(0, values.as_ptr().cast(), bytes)?, bytes })
	}
	/// A device buffer of `bytes` zeros, filled one bounded host block at a time.
	/// A zeroed buffer with `guard` zeroed bytes on both sides of it; the
	/// allocation is leaked, as the buffer never frees a pointer inside one.
	fn zeroed_guarded(runtime: &'static Gpu, bytes: usize, guard: usize) -> Result<Self> {
		if guard == 0 {
			return Self::zeroed(runtime, bytes);
		}
		let whole = Self::zeroed(runtime, bytes.max(1) + 2 * guard)?;
		let inner = Self { runtime, pointer: whole.pointer + guard as u64, bytes: bytes.max(1) };
		std::mem::forget(whole);
		Ok(inner)
	}
	fn zeroed(runtime: &'static Gpu, bytes: usize) -> Result<Self> {
		let bytes = bytes.max(1);
		let buffer = Self { runtime, pointer: runtime.allocate(bytes)?, bytes };
		let zeros = vec![0_u8; bytes.min(ZERO_FILL_BYTES)];
		for offset in (0..bytes).step_by(zeros.len()) {
			buffer.write_bytes(offset, &zeros[..zeros.len().min(bytes - offset)])?;
		}
		Ok(buffer)
	}
	fn upload_float(runtime: &'static Gpu, values: &[f64], precision: Compute) -> Result<Self> {
		Self::upload(runtime, &encode_floats(values, precision))
	}
	/// Writes stored bytes run by run from where they are mapped or held, so a
	/// weight reaches the device without a host copy of its own size.
	fn write_runs(&self, offset: usize, stored: &StoredBytes) -> Result<()> {
		for (at, run) in stored.runs() {
			self.write_bytes(checked_add(offset, at, "GPU run write")?, run)?;
		}
		Ok(())
	}
	/// A device buffer of `bytes` left as allocated, for a scratch every write fills before a read.
	fn reserve(runtime: &'static Gpu, bytes: usize) -> Result<Self> {
		let bytes = bytes.max(1);
		Ok(Self { runtime, pointer: runtime.allocate(bytes)?, bytes })
	}
	/// The weight arena. A packed weight is written from where it is mapped, a
	/// stored weight the model-load kernel expands is left to that kernel, and
	/// every other node's parameters are encoded and written in place.
	fn upload_weights(runtime: &'static Gpu, graph: &Graph, precision: Compute, inference: bool) -> Result<Self> {
		let (_, bytes) = native_weight_arena(graph, precision, inference)?;
		let buffer = Self::reserve(runtime, bytes)?;
		buffer.fill_weights(graph, precision, inference)?;
		Ok(buffer)
	}
	/// Write the weight arena `upload_weights` allocates into this buffer.
	fn fill_weights(&self, graph: &Graph, precision: Compute, inference: bool) -> Result<()> {
		let (offsets, _) = native_weight_arena(graph, precision, inference)?;
		let buffer = self;
		let mut written = std::collections::BTreeSet::new();
		for (index, node) in graph.nodes.iter().enumerate() {
			if inference && external_expert(node) { continue; }
			if let Some(weight) = packed_weight(graph, index, inference) {
				if !written.insert((offsets[index], weight.bytes.len())) { continue; }
				buffer.write_runs(offsets[index], &weight.bytes)?;
			} else if !node.table() && runtime_stored_weight(graph, index, inference).is_some() {
				// The load kernel writes this node from its stored bytes.
				continue;
			} else {
				buffer.write_bytes(offsets[index], &encode_floats(&graph.parameters[node.offset..node.offset + node.parameters], node.precision))?;
			}
		}
		Ok(())
	}
	fn write_float_bytes(&self, offset: usize, values: &[f64], precision: Compute) -> Result<()> {
		let bytes = precision.bytes();
		let encoded = values.iter().flat_map(|value| precision.pack(*value).to_le_bytes().into_iter().take(bytes)).collect::<Vec<_>>();
		self.write_bytes(offset, &encoded)
	}
	fn write_bytes(&self, offset: usize, values: &[u8]) -> Result<()> {
		require(checked_add(offset, values.len(), "GPU byte write")? <= self.bytes, "GPU byte write exceeds buffer")?;
		self.runtime.upload(self.pointer + offset as u64, values.as_ptr().cast(), values.len()).map(|_| ())
	}
	fn clear(&self) -> Result<()> {
		self.clear_range(0, self.bytes)
	}
	fn clear_range(&self, offset: usize, bytes: usize) -> Result<()> {
		require(checked_add(offset, bytes, "GPU byte clear")? <= self.bytes, "GPU byte clear exceeds buffer")?;
		self.runtime.clear(self.pointer + offset as u64, bytes)
	}
	fn download<T: Copy + Default>(&self, count: usize) -> Result<Vec<T>> {
		self.download_range(0, count)
	}
	fn download_range<T: Copy + Default>(&self, offset: usize, count: usize) -> Result<Vec<T>> {
		let start = checked_mul(offset, size_of::<T>(), "GPU read offset")?;
		let mut values = std::iter::repeat_n(T::default(), count).collect::<Vec<_>>();
		require(checked_add(start, size_of_val(&*values), "GPU read")? <= self.bytes, "GPU read exceeds buffer")?;
		self.runtime.synchronize()?;
		self.runtime.download(values.as_mut_ptr().cast(), self.pointer + start as u64, size_of_val(&*values))?;
		Ok(values)
	}
	fn download_float(&self, count: usize, precision: Compute) -> Result<Vec<f64>> {
		let bytes = precision.bytes();
		self.download::<u8>(checked_mul(count, bytes, "GPU float download")?).map(|encoded| {
			encoded
				.chunks_exact(bytes)
				.map(|chunk| {
					let mut bits = [0u8; 8];
					bits[..bytes].copy_from_slice(chunk);
					precision.unpack(u64::from_le_bytes(bits))
				})
				.collect()
		})
	}
	fn download_float_bytes(&self, offset: usize, count: usize, precision: Compute) -> Result<Vec<f64>> {
		let bytes = precision.bytes();
		// Logits and hidden rows are FP32: widen them directly instead of decoding each value's bit fields.
		if precision.plain_f32() && offset % size_of::<f32>() == 0 {
			let values = self.download_range::<f32>(offset / size_of::<f32>(), count)?;
			return Ok(values.into_iter().map(|value| { let value = f64::from(value); if value.is_nan() { f64::NAN.copysign(value) } else { value } }).collect());
		}
		let encoded = self.download_range::<u8>(offset, checked_mul(count, bytes, "GPU float byte download")?)?;
		Ok(encoded
			.chunks_exact(bytes)
			.map(|chunk| {
				let mut bits = [0_u8; 8];
				bits[..bytes].copy_from_slice(chunk);
				precision.unpack(u64::from_le_bytes(bits))
			})
			.collect())
	}
}
impl Drop for Buffer {
	fn drop(&mut self) {
		self.runtime.free(self.pointer);
	}
}
